window.TAFSIR_DATA=window.TAFSIR_DATA||{};window.TAFSIR_DATA[67]={"surah": 67, "name": "الملك", "ayat": ["تَبَٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ", "ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًۭا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ", "ٱلَّذِى خَلَقَ سَبْعَ سَمَٰوَٰتٍۢ طِبَاقًۭا ۖ مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَٰنِ مِن تَفَٰوُتٍۢ ۖ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍۢ", "ثُمَّ ٱرْجِعِ ٱلْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ ٱلْبَصَرُ خَاسِئًۭا وَهُوَ حَسِيرٌۭ", "وَلَقَدْ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَجَعَلْنَٰهَا رُجُومًۭا لِّلشَّيَٰطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ ٱلسَّعِيرِ", "وَلِلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ ۖ وَبِئْسَ ٱلْمَصِيرُ", "إِذَآ أُلْقُوا۟ فِيهَا سَمِعُوا۟ لَهَا شَهِيقًۭا وَهِىَ تَفُورُ", "تَكَادُ تَمَيَّزُ مِنَ ٱلْغَيْظِ ۖ كُلَّمَآ أُلْقِىَ فِيهَا فَوْجٌۭ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌۭ", "قَالُوا۟ بَلَىٰ قَدْ جَآءَنَا نَذِيرٌۭ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ٱللَّهُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍۢ كَبِيرٍۢ", "وَقَالُوا۟ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِىٓ أَصْحَٰبِ ٱلسَّعِيرِ", "فَٱعْتَرَفُوا۟ بِذَنۢبِهِمْ فَسُحْقًۭا لِّأَصْحَٰبِ ٱلسَّعِيرِ", "إِنَّ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ لَهُم مَّغْفِرَةٌۭ وَأَجْرٌۭ كَبِيرٌۭ", "وَأَسِرُّوا۟ قَوْلَكُمْ أَوِ ٱجْهَرُوا۟ بِهِۦٓ ۖ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ", "أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ", "هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ ذَلُولًۭا فَٱمْشُوا۟ فِى مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزْقِهِۦ ۖ وَإِلَيْهِ ٱلنُّشُورُ", "ءَأَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يَخْسِفَ بِكُمُ ٱلْأَرْضَ فَإِذَا هِىَ تَمُورُ", "أَمْ أَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًۭا ۖ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ", "وَلَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ", "أَوَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ فَوْقَهُمْ صَٰٓفَّٰتٍۢ وَيَقْبِضْنَ ۚ مَا يُمْسِكُهُنَّ إِلَّا ٱلرَّحْمَٰنُ ۚ إِنَّهُۥ بِكُلِّ شَىْءٍۭ بَصِيرٌ", "أَمَّنْ هَٰذَا ٱلَّذِى هُوَ جُندٌۭ لَّكُمْ يَنصُرُكُم مِّن دُونِ ٱلرَّحْمَٰنِ ۚ إِنِ ٱلْكَٰفِرُونَ إِلَّا فِى غُرُورٍ", "أَمَّنْ هَٰذَا ٱلَّذِى يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُۥ ۚ بَل لَّجُّوا۟ فِى عُتُوٍّۢ وَنُفُورٍ", "أَفَمَن يَمْشِى مُكِبًّا عَلَىٰ وَجْهِهِۦٓ أَهْدَىٰٓ أَمَّن يَمْشِى سَوِيًّا عَلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍۢ", "قُلْ هُوَ ٱلَّذِىٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَٰرَ وَٱلْأَفْـِٔدَةَ ۖ قَلِيلًۭا مَّا تَشْكُرُونَ", "قُلْ هُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ", "وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ", "قُلْ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌۭ مُّبِينٌۭ", "فَلَمَّا رَأَوْهُ زُلْفَةًۭ سِيٓـَٔتْ وُجُوهُ ٱلَّذِينَ كَفَرُوا۟ وَقِيلَ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تَدَّعُونَ", "قُلْ أَرَءَيْتُمْ إِنْ أَهْلَكَنِىَ ٱللَّهُ وَمَن مَّعِىَ أَوْ رَحِمَنَا فَمَن يُجِيرُ ٱلْكَٰفِرِينَ مِنْ عَذَابٍ أَلِيمٍۢ", "قُلْ هُوَ ٱلرَّحْمَٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا ۖ فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَٰلٍۢ مُّبِينٍۢ", "قُلْ أَرَءَيْتُمْ إِنْ أَصْبَحَ مَآؤُكُمْ غَوْرًۭا فَمَن يَأْتِيكُم بِمَآءٍۢ مَّعِينٍۭ"], "tafasir": [{"id": "tabari", "name": "الطبري", "full": "جامع البيان عن تأويل آي القرآن", "author": "ابن جرير الطبري", "d": 310, "src": "ar-tafsir-al-tabari"}, {"id": "ibnkathir", "name": "ابن كثير", "full": "تفسير القرآن العظيم", "author": "إسماعيل بن كثير", "d": 774, "src": "ar-tafsir-ibn-kathir"}, {"id": "qurtubi", "name": "القرطبي", "full": "الجامع لأحكام القرآن", "author": "أبو عبد الله القرطبي", "d": 671, "src": "ar-tafseer-al-qurtubi"}, {"id": "baghawi", "name": "البغوي", "full": "معالم التنزيل", "author": "الحسين بن مسعود البغوي", "d": 516, "src": "ar-tafsir-al-baghawi"}, {"id": "ibnjawzi", "name": "ابن الجوزي", "full": "زاد المسير في علم التفسير", "author": "أبو الفرج ابن الجوزي", "d": 597, "src": "tafsir-ibn-al-jawzi"}, {"id": "ibnashur", "name": "ابن عاشور", "full": "التحرير والتنوير", "author": "محمد الطاهر ابن عاشور", "d": 1393, "src": "ar-tafseer-tahrir-al-tanwir"}, {"id": "bahr", "name": "البحر المحيط", "full": "البحر المحيط", "author": "أبو حيان الأندلسي", "d": 745, "src": "al-bahr-al-muhit"}, {"id": "adwa", "name": "أضواء البيان", "full": "أضواء البيان في إيضاح القرآن بالقرآن", "author": "محمد الأمين الشنقيطي (وتتمّته لتلميذه عطية محمد سالم من سورة المجادلة)", "d": 1393, "src": "adwa-al-bayan"}, {"id": "saadi", "name": "السعدي", "full": "تيسير الكريم الرحمن", "author": "عبد الرحمن بن ناصر السعدي", "d": 1376, "src": "ar-tafsir-as-saadi"}], "types": {"nuzul": {"name": "سبب نزول وسياق تاريخي", "color": "#b45309"}, "fadl": {"name": "فضل السورة", "color": "#a16207"}, "hadith": {"name": "حديث مرفوع", "color": "#15803d"}, "athar": {"name": "أثر عن الصحابة والتابعين", "color": "#0f766e"}, "quran": {"name": "تفسير القرآن بالقرآن (مقابلة بآية)", "color": "#1d4ed8"}, "lugha": {"name": "لغة وغريب", "color": "#7c3aed"}, "irab": {"name": "إعراب ونحو وصرف", "color": "#9333ea"}, "balagha": {"name": "بلاغة ونكت", "color": "#c026d3"}, "qiraat": {"name": "قراءات ورسم", "color": "#db2777"}, "aqida": {"name": "عقيدة", "color": "#dc2626"}, "ahkam": {"name": "أحكام وفقه", "color": "#ea580c"}, "munasaba": {"name": "مناسبات وترابط", "color": "#0369a1"}, "khilaf": {"name": "أقوال المفسرين وترجيح", "color": "#475569"}, "tafsir": {"name": "معنى وبيان", "color": "#4b5563"}, "hidaya": {"name": "هدايات وتدبر", "color": "#059669"}}, "benefits": [{"id": "tabaraka", "a": 1, "t": "lugha", "x": "«تبارك»: تعاظم وتعالى، و«بيده الملك»: ملك الدنيا والآخرة وسلطانهما، نافذٌ فيهما أمره وقضاؤه.", "s": ["tabari"]}, {"id": "fadl-munjiya-abd", "a": 1, "t": "fadl", "x": "عن ابن عباس موقوفًا: علّموا «تبارك» أهليكم وأولادكم وجيرانكم فإنها المنجية والمجادلة، تجادل عن قارئها يوم القيامة وتنجيه من عذاب القبر، وفيه: «لوددت أنها في قلب كل إنسان من أمتي». قال ابن كثير: حديث غريب، وإبراهيم بن الحكم ضعيف.", "r": "مسند عبد بن حميد", "s": ["ibnkathir", "qurtubi"]}, {"id": "fadl-ibn-asakir", "a": 1, "t": "hadith", "x": "حديث أنس في رجل لم يكن معه من القرآن إلا «تبارك» فشفعت له في قبره وسمّاها النبي ﷺ «المنجية»: قال ابن كثير: منكر جدًّا، فيه فرات بن السائب ضعّفه أحمد وابن معين والبخاري وغيرهم. وللبيهقي عن ابن مسعود موقوفًا ومرفوعًا ما يشهد لأصل المعنى.", "r": "تاريخ دمشق لابن عساكر؛ إثبات عذاب القبر للبيهقي", "s": ["ibnkathir"], "n": "أصل فضل السورة ثابت بحديث أبي هريرة عند الترمذي وغيره."}, {"id": "mulk-tasarruf", "a": 1, "t": "aqida", "x": "«بيده الملك»: هو المتصرّف في جميع المخلوقات بما يشاء، لا معقّب لحكمه، ولا يُسأل عما يفعل لقهره وحكمته وعدله.", "s": ["ibnkathir", "adwa"]}, {"id": "makkiya", "a": 1, "t": "munasaba", "x": "سورة الملك مكية بالإجماع، ثلاثون آية، ومن أسمائها: «الواقية» و«المنجية» و«المانعة».", "s": ["qurtubi", "baghawi", "ibnjawzi", "bahr", "saadi"]}, {"id": "fadl-khiba", "a": 1, "t": "hadith", "x": "ضرب صحابي خباءه على قبر لا يعلم أنه قبر، فإذا فيه إنسان يقرأ سورة الملك حتى ختمها، فقال النبي ﷺ: «هي المانعة، هي المنجية، تنجيه من عذاب القبر».", "r": "الترمذي (حسن غريب) عن ابن عباس", "s": ["qurtubi"]}, {"id": "fadl-thalathun", "a": 1, "t": "hadith", "x": "«إن سورة من كتاب الله ما هي إلا ثلاثون آية شفعت لرجل حتى أخرجته من النار وأدخلته الجنة، وهي سورة تبارك».", "r": "الترمذي (حسن) عن أبي هريرة", "s": ["qurtubi", "baghawi"]}, {"id": "fadl-ibn-masud", "a": 1, "t": "athar", "x": "ابن مسعود: إذا وُضع الميت في قبره أُتي من قِبَل رجليه فيقال: ليس لكم عليه سبيل، كان يقوم بسورة الملك، ومن قِبَل رأسه فيقول لسانه: كان يقرأ بي سورة الملك؛ هي المانعة من عذاب الله، من قرأها في ليلة فقد أكثر وأطاب.", "r": "ابن مسعود", "s": ["qurtubi", "ibnjawzi"]}, {"id": "tabaraka-qurtubi", "a": 1, "t": "lugha", "x": "«تبارك» تفاعَل من البركة؛ وقال الحسن: تقدّس، وقيل: دام، فهو الدائم الذي لا أول لوجوده ولا آخر لدوامه.", "s": ["qurtubi"]}, {"id": "mulk-ibn-abbas", "a": 1, "t": "athar", "x": "ابن عباس: «بيده الملك»: يعزّ من يشاء ويذلّ من يشاء، ويحيي ويميت، ويغني ويفقر، ويعطي ويمنع. وقال ابن إسحاق: ملك النبوة.", "r": "ابن عباس", "s": ["qurtubi", "ibnjawzi"]}, {"id": "makkiya-bukhari", "a": 1, "t": "athar", "x": "ابن عباس: نزلت بمكة «تبارك الملك».", "r": "ابن الضريس وابن مردويه والبيهقي (الدر المنثور)", "s": ["baghawi"]}, {"id": "baraat-istihlal", "a": 1, "t": "balagha", "x": "افتُتحت السورة بما يدل على منتهى كمال الله، إيذانًا بأن ما حوته يحوم حول تنزيهه عن النقص الذي افتراه المشركون بنسبة الشركاء إليه؛ وهذا من براعة الاستهلال.", "s": ["ibnashur"]}, {"id": "tabaraka-tafaul", "a": 1, "t": "lugha", "x": "«تبارك» يدل على المبالغة في وفرة الخير، وصيغة «تفاعَل» إذا أُسندت إلى واحد دلّت على قوة الفعل وشدته؛ وفي مقام الثناء تقتضي أن كل وفرة من الكمال ثابتة لله.", "s": ["ibnashur"]}, {"id": "tabaraka-khabar-insha", "a": 1, "t": "balagha", "x": "«تبارك» يحتمل الإخبار عن عظمة الله، ويحتمل مع ذلك إنشاء ثناءٍ أثنى به على نفسه وتعليمًا للناس كيف يثنون عليه، كما في «الحمد لله رب العالمين».", "s": ["ibnashur"]}, {"id": "mawsul-ishtihar", "a": 1, "t": "balagha", "x": "جُعل المسند إليه اسمًا موصولًا («الذي بيده الملك») للإيذان بأن الصلة مما اشتهر به حتى أغنت عن الاسم العلم، إذ يعلم كل أحد أن الملك المطلق لا يكون إلا لله.", "s": ["ibnashur"]}, {"id": "bi-yadihi-qasr", "a": 1, "t": "balagha", "x": "تقديم المسند «بيده» لإفادة الاختصاص: الملك بيده لا بيد غيره؛ وهو قصر ادعائي لا يعتدّ بملك غيره لأنه ناقص لا يعمّ ومعرّض للزوال: ﴿فتعالى الله الملك الحق﴾.", "r": "طه: 114", "s": ["ibnashur"]}, {"id": "yad-tamthil", "a": 1, "t": "balagha", "x": "«بيده»: تمثيلٌ للتصرف المطلق في الممكنات إيجادًا وإعدامًا وتغييرًا بهيئة إمساك اليد بالشيء المملوك، والباء بمعنى «في» أو للسببية، والتعريف في «الملك» للاستغراق.", "s": ["ibnashur"]}, {"id": "mulk-milk", "a": 1, "t": "lugha", "x": "«المُلك» بالضم أكمل أحوال «المِلك» بالكسر: تصرف في طائفة من الناس ووطنهم تصرفًا كاملًا بتدبير ورعاية؛ فكل مُلك مِلك، وليس كل مِلك مُلكًا.", "s": ["ibnashur"]}, {"id": "qadir-tatmim", "a": 1, "t": "balagha", "x": "«وهو على كل شيء قدير» تعميم بعد تخصيص: الصلة أفادت تصرفه في الموجودات، وهذه أفادت تصرفه في الموجودات والمعدومات إيجادًا وإعدامًا؛ وتقديم «على كل شيء» للاهتمام بالتعميم وإبطال إلهية الأصنام.", "s": ["ibnashur"]}, {"id": "shay-madum", "a": 1, "t": "aqida", "x": "«شيء»: ما يصح أن يُعلم ويُخبر عنه؛ وخلاف المتكلمين في إطلاق «الشيء» على المعدوم خلاف لفظي مبني على الاصطلاح لا على اللغة.", "s": ["ibnashur"]}, {"id": "munasaba-tahrim-mulk", "a": 1, "t": "munasaba", "x": "مناسبتها لسورة التحريم: لمّا ضرب المثل بامرأتي نوح ولوط وقد حُتم لهما بالشقاوة وهما تحت نبيين، وبآسية ومريم وقد حُتم لهما بالجنة وقومهما كفار، كان ذلك تصرفًا في ملكه على ما سبق قضاؤه؛ فقال: «تبارك الذي بيده الملك».", "s": ["bahr"]}, {"id": "yad-kinaya", "a": 1, "t": "balagha", "x": "«بيده الملك» كناية عن الإحاطة والقهر وتحقيق الملك، إذ اليد في عرف الناس آلة التملك، ونظيره ﴿بيده ملكوت كل شيء﴾ و﴿بيدك الخير﴾؛ والملك هنا مطلق لا يبيد ولا يختل.", "s": ["bahr"]}, {"id": "malik-mulk", "a": 1, "t": "quran", "x": "ابن عباس: «الملك» ملك الملوك، لقوله: ﴿قل اللهم مالك الملك﴾.", "r": "آل عمران: 26", "s": ["ibnashur", "bahr"]}, {"id": "tabaraka-adwa", "a": 1, "t": "lugha", "x": "«تبارك» تفاعَل من البركة: تكاثرت البركات والخيرات من قِبَله، وهو يستلزم عظمته وتقديسه؛ ولا يُصرَّف ولا يُطلق إلا على الله.", "s": ["adwa"]}, {"id": "tabaraka-yasin", "a": 1, "t": "quran", "x": "تقديم «تبارك» على الموصول وصلته يدل على عظمته، ونظيره: ﴿فسبحان الذي بيده ملكوت كل شيء وإليه ترجعون﴾؛ فالتسبيح كالتبارك والموصول بعدهما سواء.", "r": "يس: 83", "s": ["adwa"]}, {"id": "malik-malik", "a": 1, "t": "aqida", "x": "تجتمع هنا صفتا المَلِك والمالك: فالذي بيده الملك وملكوت كل شيء هو المالك له والملك عليه.", "s": ["adwa"]}, {"id": "tabaraka-saadi", "a": 1, "t": "aqida", "x": "«تبارك»: تعاظم وكثر خيره وعمّ إحسانه؛ ومن عظمته أن بيده ملك العالم العلوي والسفلي، يتصرف فيه بالأحكام القدرية والأحكام الدينية التابعة لحكمته.", "s": ["saadi"]}, {"id": "death-humble", "a": 2, "t": "athar", "x": "قتادة: أذلّ الله ابنَ آدم بالموت، وجعل الدنيا دار حياة وفناء، والآخرة دار جزاء وبقاء. ورُوي عنه مرسلًا مرفوعًا: «إن الله أذلّ ابن آدم بالموت».", "r": "قتادة", "s": ["tabari", "ibnkathir", "qurtubi", "baghawi"]}, {"id": "ibtila", "a": 2, "t": "tafsir", "x": "«ليبلوكم أيكم أحسن عملا»: ليختبركم فينظر أيّكم له أطوع، وإلى طلب رضاه أسرع.", "s": ["tabari"]}, {"id": "aziz-ghafur", "a": 2, "t": "aqida", "x": "«العزيز»: الشديد انتقامه ممن عصاه، «الغفور»: لذنوب من تاب وأناب؛ فجمع بين الترهيب والترغيب.", "s": ["tabari", "ibnkathir", "qurtubi", "baghawi", "saadi"]}, {"id": "mawt-wujudi", "a": 2, "t": "aqida", "x": "استدلّ بالآية من قال إن الموت أمر وجوديّ لأنه مخلوق.", "s": ["ibnkathir", "adwa"]}, {"id": "mawt-adam-baqara", "a": 2, "t": "quran", "x": "قد يُراد بالموت العدمُ السابق وبالحياة هذه النشأة، كقوله: ﴿كيف تكفرون بالله وكنتم أمواتا فأحياكم ثم يميتكم ثم يحييكم﴾.", "r": "البقرة: 28", "s": ["ibnkathir"]}, {"id": "ahsan-la-akthar", "a": 2, "t": "hidaya", "x": "«أحسن عملا» أي خيرَه عملًا، ولم يقل: أكثر عملًا (محمد بن عجلان)؛ فالعبرة بالإحسان لا بالكثرة.", "r": "محمد بن عجلان", "s": ["ibnkathir"]}, {"id": "taqdim-mawt", "a": 2, "t": "balagha", "x": "قُدّم الموت على الحياة: لأنه إلى القهر أقرب، أو لأنه أقدم (فالأشياء ابتداءً كانت في حكم الموت كالنطفة والتراب)، أو لأن أقوى الناس داعيًا إلى العمل من نصب موته بين عينيه.", "s": ["qurtubi", "baghawi", "bahr"]}, {"id": "mawt-haqiqa", "a": 2, "t": "aqida", "x": "الموت ليس عدمًا محضًا ولا فناءً صِرفًا، بل انقطاع تعلّق الروح بالبدن ومفارقته، وانتقال من دار إلى دار؛ والحياة عكسه.", "s": ["qurtubi"]}, {"id": "mawt-kabsh", "a": 2, "t": "khilaf", "x": "ما حُكي عن ابن عباس والكلبي ومقاتل أن الموت جسمٌ في هيئة كبش والحياة فرسٌ بلقاء: قال القرطبي: يحتاج إلى خبر صحيح؛ والثابت أن الموت يُمثَّل كبشًا في الآخرة فيُذبح، وأن الله هو المميت حقيقةً والملائكة وسائط.", "s": ["qurtubi", "baghawi"], "n": "ثبت في الصحيحين أن الموت يُؤتى به يوم القيامة كهيئة كبش أملح فيُذبح، أما وصف الحياة بالفرس فلا يصح."}, {"id": "mawt-wasait", "a": 2, "t": "quran", "x": "نُسب التوفّي إلى ملك الموت ﴿قل يتوفاكم ملك الموت﴾، وإلى الملائكة ﴿توفته رسلنا﴾، وإلى الله ﴿الله يتوفى الأنفس حين موتها﴾؛ فالملائكة وسائط والله هو المميت على الحقيقة.", "r": "السجدة: 11؛ الأنعام: 61؛ الزمر: 42", "s": ["qurtubi"]}, {"id": "mawt-nutfa", "a": 2, "t": "athar", "x": "مقاتل: خلق الموت: النطفة والعلقة والمضغة، وخلق الحياة: نفخ الروح فيه. واستحسنه القرطبي.", "r": "مقاتل", "s": ["qurtubi"]}, {"id": "ahsan-awra", "a": 2, "t": "hadith", "x": "«أيكم أحسن عملا»: رُوي مرفوعًا: «أحسنُ عقلًا، وأورعُ عن محارم الله، وأسرعُ في طاعة الله»، وفي رواية: «وأشدكم خوفًا، وأحسنكم في أمره ونهيه نظرًا وإن كان أقلكم تطوعًا».", "r": "عن ابن عمر (ذكره القرطبي والبغوي وأبو حيان)", "s": ["qurtubi", "baghawi", "bahr"]}, {"id": "ahsan-suddi", "a": 2, "t": "athar", "x": "السدي: «أحسن عملا»: أكثركم للموت ذكرًا، وأحسنكم له استعدادًا، وأشدكم منه خوفًا وحذرًا.", "r": "السدي", "s": ["qurtubi"]}, {"id": "talata-tata", "a": 2, "t": "hadith", "x": "«لولا ثلاث ما طأطأ ابنُ آدم رأسه: الفقر والمرض والموت».", "r": "عن أبي الدرداء (ذكره القرطبي)", "s": ["qurtubi"]}, {"id": "ayyukum-irab", "a": 2, "t": "irab", "x": "لم يقع فعل البلوى على «أيّ» لأن بينهما فعلًا مضمرًا: ليبلوكم فينظرَ أيكم أحسن؛ فـ«أيكم» مبتدأ و«أحسن» خبره، ونظيره: ﴿سلهم أيهم بذلك زعيم﴾ (الفراء والزجاج). وقال الزجاج: اللام متعلقة بخلق الحياة لا الموت.", "s": ["qurtubi", "baghawi", "ibnjawzi"]}, {"id": "mawt-dunya-akhira", "a": 2, "t": "khilaf", "x": "«خلق الموت والحياة»: عطاء عن ابن عباس: الموت في الدنيا والحياة في الآخرة؛ وقتادة: موت الإنسان وحياته في الدنيا.", "s": ["baghawi"]}, {"id": "fudayl-akhlas", "a": 2, "t": "athar", "x": "الفضيل بن عياض: «أحسن عملا»: أخلصه وأصوبه؛ فالعمل لا يُقبل حتى يكون خالصًا صوابًا: الخالص ما كان لله، والصواب ما كان على السنة.", "r": "الفضيل بن عياض", "s": ["baghawi", "saadi"]}, {"id": "hasan-azhad", "a": 2, "t": "athar", "x": "الحسن البصري: «أحسن عملا»: أيكم أزهد في الدنيا وأترك لها.", "r": "الحسن البصري", "s": ["baghawi", "bahr"]}, {"id": "hasan-mawt", "a": 2, "t": "athar", "x": "الحسن: خلق الموتَ المزيلَ للحياة، والحياةَ التي هي ضد الموت.", "r": "الحسن البصري", "s": ["ibnjawzi"]}, {"id": "ilm-wuqu", "a": 2, "t": "aqida", "x": "«ليبلوكم فيعلمَ أيكم أحسن»: هو علمُ وقوعٍ (ظهورٍ يترتب عليه الجزاء)، لا علمٌ مستأنف؛ فالله عالم بما سيكون قبل كونه (الزجاج).", "s": ["ibnjawzi"]}, {"id": "hayat-ibtila-mawt-jaza", "a": 2, "t": "tafsir", "x": "خلق الحياة ليختبركم فيها، وخلق الموت ليبعثكم ويجازيكم؛ ولذا قيل: اللام في «ليبلوكم» متعلقة بخلق الحياة دون الموت.", "s": ["ibnjawzi"]}, {"id": "ayyu-kahf", "a": 2, "t": "quran", "x": "نظير رفع «أيّ» بالابتداء وتعليق الفعل عنها: ﴿لنعلم أي الحزبين أحصى﴾.", "r": "الكهف: 12", "s": ["ibnjawzi"]}, {"id": "mawt-hayat-ithar", "a": 2, "t": "balagha", "x": "أوثر ذكر الموت والحياة من بين المخلوقات لأنهما أعظم عوارض الحيوان الذي الإنسانُ نوعٌ منه وهو المخاطب بالشرائع، وللعبرة بتداول العرضين المتضادين على معروض واحد.", "s": ["ibnashur"]}, {"id": "khalq-mawt-asbab", "a": 2, "t": "aqida", "x": "خلق الحياة: خلق الحيّ، وخلق الموت: إيجاد أسبابه؛ لأن الموت عدم الحياة عما شأنه الحياة (تقابل العدم والملكة)، فعُبّر عنه بالخلق تبعًا كقوله: ﴿والله خلقكم وما تعملون﴾.", "r": "الصافات: 96", "s": ["ibnashur"]}, {"id": "imata-qahr", "a": 2, "t": "aqida", "x": "الإماتة مظهر عظيم للقدرة لأنها تصرف في حيٍّ يدفع عن نفسه ما يكره، ففيها تجلّي وصف القاهر؛ والإحياء مظهر للقدرة مقرونة بالإنعام ودقة الصنع.", "s": ["ibnashur"]}, {"id": "taqdim-mawt-jaza", "a": 2, "t": "balagha", "x": "التقدير: خلق الموت والحياة لتحيَوا فيبلوكم، وتموتوا فتُجزَوا؛ ولكون الجزاء بعد الموت هو المقصود الأهم قُدّم الموت على الحياة.", "s": ["ibnashur"]}, {"id": "abath-muminun", "a": 2, "t": "quran", "x": "الابتلاء مُشعر بالجزاء، تذكيرًا بحكمة خلق الإنسان وأنه لم يُخلق عبثًا: ﴿أفحسبتم أنما خلقناكم عبثا وأنكم إلينا لا ترجعون﴾، وفيه استدلال بالأنفس: ﴿وفي أنفسكم أفلا تبصرون﴾.", "r": "المؤمنون: 115؛ الذاريات: 21", "s": ["ibnashur"]}, {"id": "tail-la-hasr", "a": 2, "t": "aqida", "x": "تعليل الفعل بعلة لا يقتضي انحصار علله فيها؛ فـ«ليبلوكم» إحدى حِكَم خلق الحياة، وبناء العالم على ناموس الموت والحياة له حكم عظيمة يعسر الاطلاع عليها.", "s": ["ibnashur"]}, {"id": "ayyukum-tahdid", "a": 2, "t": "irab", "x": "في «أيكم أحسن عملا» أوجه: سادّة مسدّ المفعول الثاني والفعل معلّق (الفراء والزجاج)، أو في محل المفعول الثاني بلا تعليق (الكشاف)؛ وأجاز ابن عاشور الوقف على «ليبلوكم» وجعل الاستفهام مستأنفًا للتحضيض على حسن العمل.", "s": ["ibnashur"]}, {"id": "ahsan-fahwa", "a": 2, "t": "balagha", "x": "«أحسن عملا» يدل بالفحوى على البلوى في السيئات من باب أولى؛ فالأعمال الحسنة متفاوتة، والسيئات أولى بالإحصاء والجزاء؛ ففي الآية إيجاز.", "s": ["ibnashur"]}, {"id": "aziz-ghafur-tadhyil", "a": 2, "t": "balagha", "x": "«وهو العزيز الغفور» تذييل: «العزيز» يناسب الجزاء على المخالفات وهو حظ المشركين، و«الغفور» يناسب الجزاء على الطاعات والصفح عن فلتات الأولياء: ﴿وإني لغفار لمن تاب وآمن﴾.", "r": "طه: 82", "s": ["ibnashur"]}, {"id": "mawt-dunya-kinaya", "a": 2, "t": "balagha", "x": "قيل: كنّى بالموت عن الدنيا لأنه واقع فيها، وبالحياة عن الآخرة إذ لا موت فيها؛ أي خلق الدنيا والآخرة؛ وقُدّم الموت لأنه أهيب في النفوس.", "s": ["bahr"]}, {"id": "balwa-istiara", "a": 2, "t": "balagha", "x": "سمّى علمَه بما يقع منهم باختيارهم «بلوى» استعارةً من فعل المختبِر، والله عالم بكل شيء قبل وقوعه.", "s": ["ibnashur", "bahr"]}, {"id": "taliq-zamakhshari", "a": 2, "t": "irab", "x": "«أيكم أحسن عملا» جملة في موضع المفعول الثاني لـ«يبلو» المضمّن معنى العلم؛ ومنع الزمخشري تسميته تعليقًا، والنحاة يسمّونه تعليقًا؛ وقدّر الحوفي وابن عطية: فينظرَ أو فيعلمَ.", "s": ["bahr"]}, {"id": "mawtatan", "a": 2, "t": "quran", "x": "جعل للعالم موتتين وإحياءتين، وبيّنه: ﴿كيف تكفرون بالله وكنتم أمواتا فأحياكم ثم يميتكم ثم يحييكم﴾؛ وانظر ﴿وما خلقت الجن والإنس إلا ليعبدون﴾ و﴿ليبلوكم أيكم أحسن عملا﴾ في هود.", "r": "البقرة: 28؛ الذاريات: 56؛ هود: 7", "s": ["adwa"]}, {"id": "mawt-wujudi-falasifa", "a": 2, "t": "aqida", "x": "الموت أمر وجودي لا عدمي كما زعم الفلاسفة، لأنه لو كان عدميًّا لما تعلّق به الخلق.", "s": ["adwa"]}, {"id": "ibtila-shahawat", "a": 2, "t": "hidaya", "x": "خلق الله العباد وأخبرهم أنهم سينقلون من هذه الدار، وأمرهم ونهاهم وابتلاهم بالشهوات المعارضة لأمره؛ فمن انقاد وأحسن العمل أحسن الله له الجزاء في الدارين، ومن مال مع شهواته فله شر الجزاء.", "s": ["saadi"]}, {"id": "ghafur-saadi", "a": 2, "t": "hidaya", "x": "«الغفور» عن المسيئين والمقصرين، خصوصًا إذا تابوا وأنابوا؛ يغفر ذنوبهم ولو بلغت عنان السماء، ويستر عيوبهم ولو كانت ملء الدنيا.", "s": ["saadi"]}, {"id": "tibaq", "a": 3, "t": "lugha", "x": "«طباقا»: طبقًا فوق طبق، بعضها فوق بعض.", "s": ["tabari", "baghawi", "ibnjawzi", "saadi"]}, {"id": "tafawut", "a": 3, "t": "lugha", "x": "«من تفاوت»: من اختلاف (قتادة)؛ فلا ترى في خلق الرحمن – سماءً ولا أرضًا – اختلافًا ولا تناقضًا.", "s": ["tabari", "ibnkathir", "qurtubi", "baghawi"]}, {"id": "qiraa-tafawut", "a": 3, "t": "qiraat", "x": "قرأ عامة قراء الكوفة «من تفوُّت» بتشديد الواو بلا ألف، والباقون «تفاوت»؛ وهما لغتان بمعنى واحد كتصاعر وتصعّر وتعاهد وتعهّد.", "s": ["tabari", "qurtubi", "baghawi", "ibnjawzi", "ibnashur"]}, {"id": "futur", "a": 3, "t": "lugha", "x": "«فطور»: صدوع وشقوق وخلل؛ ابن عباس: الوَهْي، قتادة: الخلل، سفيان: الشقوق.", "s": ["tabari", "ibnkathir", "qurtubi", "baghawi", "ibnjawzi", "bahr"]}, {"id": "futur-quran", "a": 3, "t": "quran", "x": "«فطور» من الفَطْر وهو الشق، ونظيره: ﴿تكاد السماوات يتفطرن من فوقهن﴾ أي يتشققن.", "r": "الشورى: 5", "s": ["tabari"]}, {"id": "tibaq-khala", "a": 3, "t": "khilaf", "x": "«طباقا»: هل السماوات متلاصقة أو متفاصلة بينها خلاء؟ قولان، أصحهما الثاني كما دل عليه حديث الإسراء وغيره.", "s": ["ibnkathir"]}, {"id": "tibaq-irab", "a": 3, "t": "irab", "x": "«طباقا»: نعت لـ«سبع» وصفٌ بالمصدر، أو مصدرٌ أي طوبقت طباقًا، أو مفعول ثانٍ على أن «خلق» بمعنى جعل (سيبويه). وهي جمع طَبَق كجمل وجمال، وقيل جمع طبقة. وعن ابن عباس: الملتزق منها أطرافها.", "s": ["qurtubi", "bahr"]}, {"id": "tafawut-abu-ubayd", "a": 3, "t": "khilaf", "x": "اختار أبو عبيد «تفوّت» واحتج بحديث «أمثلي يُتفوَّت عليه في بناته»، وردّه النحاس بأن «تفاوت» بمعنى التباين أشبه بسياق الآية.", "s": ["qurtubi"]}, {"id": "fa-irji", "a": 3, "t": "irab", "x": "جاء «فارجع» بالفاء ولم يتقدمه فعل أمر لأن قوله «ما ترى» في معنى: انظر، ثم ارجع البصر (قتادة).", "s": ["qurtubi"]}, {"id": "futur-shir", "a": 3, "t": "lugha", "x": "أصل الفطور الانشقاق، ومنه قول الشاعر: «بنى لكم بلا عمدٍ سماءً ... وزيّنها فما فيها فطورُ».", "s": ["qurtubi", "bahr"]}, {"id": "tafawut-ibn-qutayba", "a": 3, "t": "lugha", "x": "ابن قتيبة: التفاوت الاضطراب والاختلاف، وأصله من الفَوْت وهو أن يفوت شيءٌ شيئًا فيقع الخلل، والسماء متصل بعضها ببعض.", "s": ["ibnjawzi"]}, {"id": "hal-tara-idgham", "a": 3, "t": "qiraat", "x": "قرأ أبو عمرو وحمزة والكسائي «هَتّرى» بإدغام لام «هل» في التاء، والباقون بالإظهار.", "s": ["ibnjawzi"]}, {"id": "samawat-ibn-ashur", "a": 3, "t": "khilaf", "x": "رأى ابن عاشور أن الظاهر في «سبع سماوات» الكواكب التي هي مجموع النظام الشمسي سوى الأرض لأنها المشاهدة للمخاطبين، وأن «طباقا» تعني تماثلها وتناسبها في النظام لا أن بعضها ظرف لبعض؛ وهو اجتهاد منه يخالف ظاهر قول الجمهور.", "s": ["ibnashur"], "n": "اجتهاد لابن عاشور يخالف ظاهر قول جمهور المفسرين في أن السماوات سبع أجرام طباق بعضها فوق بعض."}, {"id": "tibaq-shann", "a": 3, "t": "lugha", "x": "«طباقا»: مصدر طابق وُصف به للمبالغة، أو جمع «طَبَق» وهو المساوي، ومنه المثل: «وافق شنٌّ طبقه».", "s": ["ibnashur"]}, {"id": "tafawut-fawt", "a": 3, "t": "lugha", "x": "التفاوت: شدة الفوت، والفوت: البعد؛ وليست صيغة التفاعل فيه للمشاركة بل للمبالغة، واستُعير لعدم التناسق تشبيهًا للمعقول بالمحسوس.", "s": ["ibnashur"]}, {"id": "rasm-tafawut", "a": 3, "t": "qiraat", "x": "قرأ حمزة والكسائي وخلف «تفوُّت»، و«تفاوت» مرسومة في المصحف بغير ألف كما هو كثير في رسم الفتحات المشبعة، فاحتملت القراءتين.", "s": ["ibnashur"]}, {"id": "tarid-mushrikin", "a": 3, "t": "balagha", "x": "الخطاب «ما ترى» لغير معيّن، والمقصود التعريض بالمشركين الذين أضاعوا النظر في نظام الكواكب الدال على الوحدانية.", "s": ["ibnashur"]}, {"id": "rahman-nizam", "a": 3, "t": "balagha", "x": "التعبير بـ«الرحمن» دون اسم الجلالة إيماء إلى أن هذا النظام مقتضى رحمته بالناس لتنتظم معايشهم ﴿لتعلموا عدد السنين والحساب﴾، وفيه تورّك على المشركين إذ أنكروا اسم «الرحمن» ﴿قالوا وما الرحمن﴾.", "r": "يونس: 5؛ الفرقان: 60", "s": ["ibnashur"]}, {"id": "nazar-wajib", "a": 3, "t": "ahkam", "x": "صيغة الأمر «فارجع البصر» للإرشاد في حق المشركين، وللوجوب في حق المسلمين؛ فالنظر في أدلة الصفات واجب لمن عرض له داعٍ إلى الاستدلال، والمراد بصرٌ مصحوب بالتفكر لا بالتقليد.", "s": ["ibnashur"]}, {"id": "hal-taqriri", "a": 3, "t": "balagha", "x": "الاستفهام في «هل ترى من فطور» تقريري، و«هل» بمعنى «قد» تفيد التأكيد والحث: لا تقنع بنظرة أو نظرتين بل كرّر النظر باحثًا.", "s": ["ibnashur"]}, {"id": "tafawut-aqwal", "a": 3, "t": "lugha", "x": "«تفاوت»: تفرّق (ابن عباس)، عيب (السدي)، عدم استواء (عطاء بن يسار)، وأصله من الفوت (ثعلب)؛ وحدّه: تجاوز الحدّ الذي تجب له زيادة أو نقص، أي عدم التناسب.", "s": ["bahr"]}, {"id": "tafawut-qiraa-shadhdha", "a": 3, "t": "qiraat", "x": "قرأ ابن مسعود وعلقمة والأسود وابن جبير وطلحة والأعمش «تفوُّت» بشد الواو، والجمهور «تفاوت»؛ وحكى أبو زيد ضمّ الواو وفتحها وكسرها في «تفاوُت»، والفتح والكسر شاذان.", "s": ["bahr"]}, {"id": "khalq-rahman-wad", "a": 3, "t": "balagha", "x": "جعل الزمخشري «ما ترى في خلق الرحمن» صفة لـ«طباقا» وأصلها: ما ترى فيهن، فوضع الظاهر «خلق الرحمن» موضع الضمير تعظيمًا لخلقهن وتنبيهًا على سبب سلامتهن من التفاوت وهو أنه خلق الرحمن.", "s": ["bahr"]}, {"id": "fa-sababiyya", "a": 3, "t": "balagha", "x": "الفاء في «فارجع البصر» للتسبب: لمّا أخبر أنه لا تفاوت أمر بترديد البصر ليطابق العِيانُ الخبر.", "s": ["ibnashur", "bahr"]}, {"id": "khalq-rahman-am", "a": 3, "t": "quran", "x": "«في خلق الرحمن» عام في جميع المخلوقات من الإتقان والحكمة: ﴿صنع الله الذي أتقن كل شيء﴾، ﴿الذي أعطى كل شيء خلقه ثم هدى﴾، ﴿الذي أحسن كل شيء خلقه﴾؛ وإتقان كل شيء بحسبه.", "r": "النمل: 88؛ طه: 50؛ السجدة: 7", "s": ["bahr", "adwa"]}, {"id": "furuj-qaf", "a": 3, "t": "quran", "x": "نظيرها: ﴿أفلم ينظروا إلى السماء فوقهم كيف بنيناها وزيناها وما لها من فروج﴾، و﴿وجعلنا السماء سقفا محفوظا﴾.", "r": "ق: 6؛ الأنبياء: 32", "s": ["adwa"]}, {"id": "infitar-qiyama", "a": 3, "t": "quran", "x": "نفي الفطور حال السماء في الدنيا فقط، وستنفطر يوم القيامة: ﴿إذا السماء انفطرت﴾، ﴿إذا السماء انشقت﴾، ﴿ويوم تشقق السماء بالغمام﴾.", "r": "الانفطار: 1؛ الانشقاق: 1؛ الفرقان: 25", "s": ["ibnashur", "adwa"]}, {"id": "munasaba-ihsan-khalq", "a": 3, "t": "munasaba", "x": "مجيء «ما ترى في خلق الرحمن من تفاوت» بعد «ليبلوكم أيكم أحسن عملا» توجيهٌ إلى حُسن صنع الله وإتقانه؛ فمن أحسن الخلق يطلب من عباده إحسان العمل.", "s": ["adwa"]}, {"id": "tafawut-kamal", "a": 3, "t": "hidaya", "x": "إذا انتفى النقص من كل وجه صارت السماء كاملة متناسبة في لونها وهيئتها وارتفاعها وما فيها من الشمس والقمر والكواكب؛ ولما كان كمالها معلومًا أمر بتكرار النظر إليها نظر اعتبار.", "s": ["saadi"]}, {"id": "khasi-hasir", "a": 4, "t": "lugha", "x": "«خاسئا»: صاغرًا مُبعدًا (من قولهم للكلب: اخسأ)، و«حسير»: كليل منقطع مُعْيٍ لم يرَ خللًا.", "s": ["tabari", "ibnkathir", "qurtubi", "baghawi", "ibnjawzi", "saadi"]}, {"id": "karratayn", "a": 4, "t": "tafsir", "x": "«كرّتين»: مرة بعد مرة، والمراد التكرار والإلحاح في النظر؛ فمهما كرّر البصر رجع عاجزًا عن إيجاد خلل.", "s": ["tabari", "ibnkathir", "baghawi", "ibnjawzi"]}, {"id": "karratayn-takthir", "a": 4, "t": "balagha", "x": "«كرتين» في موضع المصدر، والمراد بها التكثير لا التثنية بدليل «خاسئا وهو حسير»؛ وأُمر بالنظر مرة بعد مرة لأن الإنسان قد لا يرى عيب الشيء من النظرة الأولى.", "s": ["qurtubi", "bahr", "saadi"]}, {"id": "hasir-shir", "a": 4, "t": "lugha", "x": "«حسير»: بلغ الغاية في الإعياء (فعيل بمعنى فاعل)، أو مفعول من حسره بُعدُ الشيء؛ وشاهده: «فعاد إليّ الطرفُ وهو حسيرُ». وقيل: الحسير النادم.", "s": ["qurtubi", "bahr", "adwa"]}, {"id": "kab-samawat", "a": 4, "t": "athar", "x": "عن كعب الأحبار: السماء الدنيا موج مكفوف، والثانية مرمرة بيضاء، والثالثة حديد، والرابعة نحاس، والخامسة فضة، والسادسة ذهب، والسابعة ياقوتة حمراء؛ وهي من الإسرائيليات التي تحتاج إلى نقل صحيح (كما عقّب أبو حيان).", "r": "كعب الأحبار", "s": ["baghawi", "bahr"], "n": "من الإسرائيليات، لا يُعتمد عليها."}, {"id": "hasir-zajjaj", "a": 4, "t": "lugha", "x": "الزجاج: «حسير» قد أعيا من قبل أن يرى في السماء خللًا.", "s": ["ibnjawzi"]}, {"id": "thumma-rutbi", "a": 4, "t": "balagha", "x": "«ثم» في «ثم ارجع البصر» للتراخي الرتبي؛ لأن إعادة النظر تزيد اليقين بانتفاء التفاوت رسوخًا.", "s": ["ibnashur"]}, {"id": "karratayn-ijaz", "a": 4, "t": "balagha", "x": "أوثر «كرّتين» على «مرتين» لأن «كرّة» لم يغلب إطلاقها على عدد الاثنين، فهي أظهر في مطلق التكرير، بخلاف ﴿الطلاق مرتان﴾ حيث أريد العدد؛ ومثلها: لبيك وسعديك ودواليك؛ وهذا من خصائص الإعجاز.", "s": ["ibnashur"]}, {"id": "yanqalib-ithar", "a": 4, "t": "balagha", "x": "أوثر «ينقلب» دون «يرجع» لئلا يلتبس بفعل «ارجع» قبله؛ وهو من دقائق الإعجاز.", "s": ["ibnashur"]}, {"id": "khasi-khaib", "a": 4, "t": "lugha", "x": "«خاسئا»: خائبًا لم يجد ما طلبه، و«حسير»: كليل من قوة التأمل والتحديق مع التكرير.", "s": ["ibnashur"]}, {"id": "karratayn-labbayk", "a": 4, "t": "irab", "x": "«كرتين» تثنية يراد بها التكثير لا شفع الواحد، كقولهم: لبّيك، أي إجابات متتالية؛ وكلالُ البصر دليل على ذلك، فالبصر لا يكلّ من نظرتين.", "s": ["ibnashur", "bahr"]}, {"id": "yanqalib-qiraa", "a": 4, "t": "qiraat", "x": "قرأ الجمهور «ينقلبْ» بالجزم جوابًا للأمر، وروى الخوارزمي عن الكسائي الرفع «ينقلبُ» على تقدير الفاء أو الحال.", "s": ["bahr"]}, {"id": "nazar-arba", "a": 4, "t": "balagha", "x": "النظر المطلوب حقيقةً أربع مرات: «ما ترى» (1)، «فارجع البصر» (2)، «ثم ارجع البصر كرتين» (3 و4)؛ وليس بعد معاودة النظر أربعًا تأكيد.", "s": ["adwa"]}, {"id": "nujum-thalath", "a": 5, "t": "athar", "x": "قتادة: خلق الله النجوم لثلاث: زينةً للسماء الدنيا، ورجومًا للشياطين، وعلاماتٍ يُهتدى بها؛ فمن تأوّل فيها غير ذلك فقد قال برأيه وأخطأ حظه وتكلّف ما لا علم له به.", "r": "قتادة", "s": ["tabari", "ibnkathir", "qurtubi", "bahr", "adwa"]}, {"id": "masabih", "a": 5, "t": "lugha", "x": "سُمّيت النجوم «مصابيح» لإضاءتها، كما سُمّي الصبح صبحًا لضوئه.", "s": ["tabari", "qurtubi", "baghawi"]}, {"id": "masabih-kawakib", "a": 5, "t": "tafsir", "x": "لما نفى عن السماء النقص بيّن كمالها وزينتها؛ فالمصابيح هي الكواكب السيارة والثوابت.", "s": ["ibnkathir"]}, {"id": "rujum-jins", "a": 5, "t": "irab", "x": "الضمير في «وجعلناها» يعود على جنس المصابيح لا على عينها؛ فالرجم لا يكون بالكواكب نفسها بل بشُهُب دونها قد تكون مستمدة منها.", "s": ["ibnkathir", "qurtubi", "bahr"]}, {"id": "rujum-saffat", "a": 5, "t": "quran", "x": "نظيرها: ﴿إنا زينا السماء الدنيا بزينة الكواكب وحفظا من كل شيطان مارد... إلا من خطف الخطفة فأتبعه شهاب ثاقب﴾.", "r": "الصافات: 6-10", "s": ["ibnkathir", "qurtubi", "adwa"]}, {"id": "rujum-zina", "a": 5, "t": "khilaf", "x": "كيف تكون الكواكب زينة وهي رجوم؟ قيل: الرجم بشهبها على حذف مضاف فالمصابيح باقية، وقيل: ينفصل منها شيء يُرجم به دون أن ينقص ضوؤها (أبو علي)، وقال القشيري: هي زينة قبل أن يُرجم بها.", "s": ["qurtubi"]}, {"id": "kahana", "a": 5, "t": "athar", "x": "محمد بن كعب: والله ما لأحد من أهل الأرض في السماء نجم، ولكنهم يتخذون الكهانة سبيلًا ويتخذون النجوم علّة؛ ففيه إبطال التنجيم.", "r": "محمد بن كعب القرظي", "s": ["qurtubi"]}, {"id": "samaa-dunya", "a": 5, "t": "lugha", "x": "«السماء الدنيا»: الدنيا من الدنوّ، أي السماء الأدنى إلى الأرض وهي التي يراها الناس.", "s": ["baghawi"]}, {"id": "rujum-istiraq", "a": 5, "t": "tafsir", "x": "«رجوما»: مرامي للشياطين إذا استرقوا السمع.", "s": ["baghawi", "ibnjawzi", "saadi"]}, {"id": "samaa-dunya-mithal", "a": 5, "t": "munasaba", "x": "انتقل من نفي الخلل عن السماوات إلى بيان إتقان السماء الدنيا خاصة، كالمثال بعد القاعدة الكلية، لأنها نُصب أعين المخاطبين، وليتخلّص منها إلى ذكر الشياطين ووعيدهم ووعيد أتباعهم.", "s": ["ibnashur"]}, {"id": "masabih-tashbih", "a": 5, "t": "balagha", "x": "تسمية النجوم «مصابيح» تشبيه بليغ في حسن المنظر، وتنكيرها للتعظيم، وذكر التزيين إدماج للامتنان في أثناء الاستدلال كقوله ﴿ولكم فيها جمال﴾.", "s": ["ibnashur"]}, {"id": "rujum-masdar", "a": 5, "t": "lugha", "x": "«رجوم» جمع رَجْم وهو المصدر سُمّي به ما يُرجم به، كالخَلْق بمعنى المخلوق.", "s": ["ibnashur"]}, {"id": "rujum-isnad", "a": 5, "t": "balagha", "x": "جعل المصابيح رجومًا من إسناد عمل البعض إلى الجميع، كإسناد الأعمال إلى القبائل والعامل بعض أفرادها؛ فالرجم ببعض النجوم المنقضّة وهي الشهب.", "s": ["ibnashur"]}, {"id": "atadna", "a": 5, "t": "lugha", "x": "«أعتدنا» أصلها «أعددنا» قُلبت الدال الأولى تاء لتقارب المخرجين طلبًا للخفة.", "s": ["ibnashur"]}, {"id": "saeer-jinn", "a": 5, "t": "quran", "x": "خُصّ عذاب الشياطين بـ«السعير» (أشد طبقات النار توقدًا) لأن نار جهنم أشد من نار طبعهم، ومثله في الجن: ﴿نذقه من عذاب السعير﴾، و﴿إنما يدعو حزبه ليكونوا من أصحاب السعير﴾.", "r": "سبأ: 12؛ فاطر: 6", "s": ["ibnashur"]}, {"id": "nar-makhluqa", "a": 5, "t": "khilaf", "x": "«أعتدنا»: يحتمل إعداد تقدير فلا يقتضي وجود جهنم الآن، أو إعداد استعمال فتكون مخلوقة؛ وذكر ابن عاشور الخلاف في وجود النار الآن (ومذهب أهل السنة أنها مخلوقة موجودة).", "s": ["ibnashur"], "n": "مذهب أهل السنة أن الجنة والنار مخلوقتان موجودتان الآن."}, {"id": "samaa-dunya-nisbi", "a": 5, "t": "lugha", "x": "«الدنيا»: الدنوّ فيها نسبي، وإلا فليست قريبة؛ و«مصابيح» مطلق لا يدل على أن غير السماء الدنيا ليس فيها مصابيح.", "s": ["bahr"]}, {"id": "rujum-qabas", "a": 5, "t": "tafsir", "x": "نُسب الرجم إلى المصابيح لأن الشهاب ينفصل من نارها والكوكب قارّ في مكانه، كالقَبَس يؤخذ من النار والنار باقية لا تنقص.", "s": ["bahr"]}, {"id": "rujum-munajjimin", "a": 5, "t": "khilaf", "x": "قيل: «رجوما» أي ظنونًا لشياطين الإنس وهم المنجمون؛ وشنّع أبو حيان على المنجمين وموالدهم وكذبهم وأنه لا يصح منها شيء؛ والظاهر أن الرجم حقيقي بالشهب.", "s": ["bahr"]}, {"id": "nazariyyat", "a": 5, "t": "hidaya", "x": "منهج في النظريات العلمية الحديثة: ما عارض صريح القرآن رُدّ (كنظرية ثبات الشمس مع ﴿والشمس تجري لمستقر لها﴾)، وما لم يعارضه ولم يُنصّ عليه نتثبّت فيه كموقف سليمان من خبر الهدهد ﴿سننظر أصدقت أم كنت من الكاذبين﴾، ولا نحمّل لفظ القرآن ما لا يحتمل.", "r": "يس: 38؛ النمل: 27", "s": ["adwa"]}, {"id": "nujum-dunya-khassa", "a": 5, "t": "aqida", "x": "مفهوم «السماء الدنيا» أن النجوم خاصة بها؛ لأن وظائفها الثلاث (زينة، رجوم، اهتداء) تتعلق بالسماء الدنيا، والشياطين لا تنفذ إلى ما فوقها لأنها محفوظة لها أبواب لا يُدخل منها إلا بإذن كما في حديث الإسراء.", "s": ["adwa"]}, {"id": "shuhub-jinn", "a": 5, "t": "quran", "x": "الرجوم هي الشهب النارية التي ترمى بها الشياطين عند استراق السمع: ﴿فمن يستمع الآن يجد له شهابا رصدا﴾، ﴿إلا من خطف الخطفة فأتبعه شهاب ثاقب﴾.", "r": "الجن: 9؛ الصافات: 10", "s": ["adwa"]}, {"id": "jinn-nar", "a": 5, "t": "aqida", "x": "كيف تحرق النارُ الجنَّ وهم من نار؟ أجاب الرازي: النار بعضها أقوى من بعض فيؤثر الأقوى في الأضعف، ويشهد له «عذاب السعير» وهو أشد النار؛ كما أن الإنسان من طين ويُقتل بقطعة فخار.", "s": ["ibnashur", "adwa"]}, {"id": "nujum-zina-saadi", "a": 5, "t": "tafsir", "x": "لولا النجوم لكانت السماء سقفًا مظلمًا لا حسن فيه؛ فجعلها الله زينة وجمالًا ونورًا وهداية في ظلمات البر والبحر، ورجومًا وحراسة من الشياطين.", "s": ["saadi"]}, {"id": "nujum-fawq", "a": 5, "t": "khilaf", "x": "لا ينافي تزيين السماء الدنيا بالمصابيح أن يكون كثير من النجوم فوق السماوات السبع؛ فالسماوات شفافة تحصل بها الزينة للسماء الدنيا وإن لم تكن الكواكب فيها.", "s": ["saadi"]}, {"id": "tatmim-kuffar", "a": 6, "t": "balagha", "x": "«وللذين كفروا بربهم عذاب جهنم» تتميم لئلا يُتوهّم أن العذاب خاص بالشياطين، وتقديم المجرور للاهتمام.", "s": ["ibnashur"]}, {"id": "adhab-nasb", "a": 6, "t": "qiraat", "x": "قرأ الجمهور «عذابُ جهنم» بالرفع، وقرأ الضحاك والأعرج والحسن (في رواية) «عذابَ» بالنصب عطفًا على «عذابَ السعير»: وأعتدنا للذين كفروا عذاب جهنم.", "s": ["bahr"]}, {"id": "atba-shayatin", "a": 6, "t": "munasaba", "x": "لما ذكر عذاب الشياطين ذكر أتباعهم من الكفار: «وللذين كفروا بربهم عذاب جهنم»، فالتابع مثل المتبوع في الجزاء.", "s": ["ibnashur", "saadi"]}, {"id": "shahiq", "a": 7, "t": "lugha", "x": "«شهيقا»: صوت يخرج من الجوف بشدة كآخر نهيق الحمار، والزفير أوله؛ واستشهد ببيت رؤبة.", "s": ["tabari", "baghawi", "ibnjawzi"]}, {"id": "tafur", "a": 7, "t": "athar", "x": "مجاهد: «وهي تفور» تغلي كما يغلي القِدْر.", "r": "مجاهد", "s": ["tabari", "ibnkathir", "qurtubi", "ibnjawzi"]}, {"id": "tafur-thawri", "a": 7, "t": "athar", "x": "«وهي تفور»: تغلي بهم كما يغلي الحَبّ القليل في الماء الكثير (نسبه ابن كثير إلى الثوري، والقرطبي إلى مجاهد).", "r": "الثوري / مجاهد", "s": ["ibnkathir", "qurtubi", "baghawi"]}, {"id": "shahiq-ibn-abbas", "a": 7, "t": "athar", "x": "ابن عباس: الشهيق لجهنم عند إلقاء الكفار فيها، تشهق إليهم شهقة البغلة للشعير ثم تزفر زفرة لا يبقى أحد إلا خاف. وقال عطاء: الشهيق من الكفار أنفسهم.", "r": "ابن عباس، عطاء", "s": ["qurtubi"]}, {"id": "shahiq-ibn-ashur", "a": 7, "t": "lugha", "x": "الشهيق: تردّد الأنفاس في الصدر لا تستطيع الصعود كما في البكاء، أُطلق على صوت التهاب جهنم تفظيعًا له؛ واللام في «سمعوا لها» تقتضي أن الشهيق شهيقها هي.", "s": ["ibnashur"]}, {"id": "ilqa-hatab", "a": 7, "t": "balagha", "x": "«أُلقوا» أي طُرحوا كما يُطرح الحطب في النار العظيمة، ومثله ﴿حصب جهنم﴾.", "s": ["bahr"]}, {"id": "shahiq-ahl", "a": 7, "t": "khilaf", "x": "«سمعوا لها شهيقا»: صوت جهنم المنكر لشدة توقدها، ويحتمل حذف مضاف: سمعوا لأهلها شهيقًا، كقوله: ﴿لهم فيها زفير وشهيق﴾.", "r": "هود: 106", "s": ["bahr"]}, {"id": "nar-idrak", "a": 7, "t": "aqida", "x": "إثبات أن للنار حسًّا وإدراكًا وإرادة: تغتاظ وتبصر وتتكلم وتطلب المزيد: ﴿إذا رأتهم من مكان بعيد سمعوا لها تغيظا وزفيرا﴾، ﴿يوم نقول لجهنم هل امتلأت وتقول هل من مزيد﴾.", "r": "الفرقان: 12؛ ق: 30", "s": ["adwa"]}, {"id": "tamayyaz", "a": 8, "t": "lugha", "x": "«تميّز من الغيظ»: تتفرّق ويفارق بعضها بعضًا وتنفطر غضبًا لله على أهل معاصيه (ابن عباس، الضحاك، ابن زيد).", "s": ["tabari", "ibnkathir", "qurtubi", "baghawi", "ibnjawzi", "bahr", "saadi"]}, {"id": "hujja-qabl-adhab", "a": 8, "t": "aqida", "x": "عدل الله: لا يعذّب أحدًا إلا بعد قيام الحجة وإرسال الرسول، كما قال: ﴿وما كنا معذبين حتى نبعث رسولا﴾.", "r": "الإسراء: 15", "s": ["ibnkathir", "adwa"]}, {"id": "khazana-zumar", "a": 8, "t": "quran", "x": "نظير سؤال الخزنة: ﴿وقال لهم خزنتها ألم يأتكم رسل منكم يتلون عليكم آيات ربكم... قالوا بلى ولكن حقت كلمة العذاب على الكافرين﴾.", "r": "الزمر: 71", "s": ["ibnkathir"]}, {"id": "tamayyaz-asl", "a": 8, "t": "irab", "x": "«تميّز» أصلها: تتميّز، حُذفت إحدى التاءين تخفيفًا.", "s": ["qurtubi", "ibnashur"]}, {"id": "sual-tawbikh", "a": 8, "t": "balagha", "x": "سؤال الخزنة «ألم يأتكم نذير» على جهة التوبيخ والتقريع لا الاستعلام.", "s": ["qurtubi", "baghawi", "ibnjawzi", "saadi"]}, {"id": "tamayyaz-tamthil", "a": 8, "t": "balagha", "x": "«تكاد تميّز من الغيظ» تمثيلية مكنية: شُبّهت حال فورانها والتهامها من يُلقى فيها بحال مغتاظٍ لا يترك شيئًا أغاظه إلا سلّط عليه أذاه، كقولهم: يكاد يتميّز غيظًا؛ ونظيرها ﴿جدارا يريد أن ينقض﴾.", "r": "الكهف: 77", "s": ["ibnashur"]}, {"id": "kullama-irab", "a": 8, "t": "irab", "x": "«كلما» مركبة من «كل» و«ما» المصدرية الظرفية، فاكتسبت معنى الشرط؛ وجيء بالفعلين ماضيين «ألقي... سألهم» لخفة الماضي مع ظهور الاستقبال؛ وضمائر الجمع للفوج باعتبار أفراده.", "s": ["ibnashur"]}, {"id": "khazana-majaz", "a": 8, "t": "lugha", "x": "«خزنة» جمع خازن وهو الحافظ للشيء في مكان حصين، وإطلاقه على الملائكة الموكلين بالنار مجاز مرسل.", "s": ["ibnashur"]}, {"id": "sual-tandim", "a": 8, "t": "balagha", "x": "الاستفهام «ألم يأتكم نذير» للتوبيخ والتنديم ليزيدهم حسرة.", "s": ["ibnashur"]}, {"id": "tamayyaz-qiraa", "a": 8, "t": "qiraat", "x": "«تميّز»: الجمهور بتاء واحدة خفيفة، والبزّي بتشديد التاء وصلًا، وطلحة بتاءين، وأبو عمرو بإدغام الدال في التاء «تكاد تّميّز»، والضحاك «تمايز».", "s": ["bahr"]}, {"id": "tamayyaz-majaz", "a": 8, "t": "balagha", "x": "«تميّز من الغيظ» مجاز: جُعلت كالمغتاظة لشدة غليانها، كقولهم: فلان يتميّز من الغيظ، و«غضب فطارت منه شقة في الأرض وشقة في السماء»؛ ويجوز أن يراد غيظ الزبانية.", "s": ["ibnashur", "bahr"]}, {"id": "sual-tawbikh-ziyada", "a": 8, "t": "hidaya", "x": "سؤال الخزنة توبيخ وتقريع، وهو مما يزيدهم عذابًا إلى عذابهم؛ وخزنتها: مالك وأعوانه.", "s": ["bahr"]}, {"id": "khazana-malaika", "a": 8, "t": "quran", "x": "خزنة النار ملائكة غلاظ شداد: ﴿عليها ملائكة غلاظ شداد لا يعصون الله ما أمرهم﴾، وعدتهم: ﴿عليها تسعة عشر﴾.", "r": "التحريم: 6؛ المدثر: 30-31", "s": ["adwa"]}, {"id": "afwaj", "a": 8, "t": "aqida", "x": "«كلما أُلقي فيها فوج»: يدخل أهل النار جماعة بعد جماعة، كقوله: ﴿كلما دخلت أمة لعنت أختها﴾.", "r": "الأعراف: 38", "s": ["adwa"]}, {"id": "nadhir-faeel", "a": 8, "t": "lugha", "x": "«نذير» فعيل بمعنى مُفعِل (مُنذِر)، كـ﴿بديع السماوات﴾ أي مُبدع، و«أليم» أي مؤلم، ومنه «الداعي السميع» أي المُسمِع؛ والإنذار: إعلام مقترن بتخويف.", "s": ["adwa"]}, {"id": "tamayyaz-zann", "a": 8, "t": "hidaya", "x": "«تكاد تميّز من الغيظ»: تكاد تتقطع من شدة غيظها على الكفار قبل دخولهم؛ فما ظنك بما تفعل بهم إذا حصلوا فيها؟!", "s": ["saadi"]}, {"id": "dalal-kabir-khazana", "a": 9, "t": "khilaf", "x": "«إن أنتم إلا في ضلال كبير»: الأظهر أنه من قول الكفار للرسل في الدنيا، وقيل: هو من قول الخزنة لأهل النار.", "s": ["qurtubi", "ibnashur", "bahr"]}, {"id": "bala-taarud", "a": 9, "t": "balagha", "x": "جملة «قالوا بلى قد جاءنا نذير» معترضة تشير إلى أن الفوج قاطع كلام الخزنة بتعجيل الاعتراف من شدة الخوف؛ وتكرير معنى «بلى» بـ«قد جاءنا نذير» من تكرير المتحسّر، وهو مناط الندامة.", "s": ["ibnashur"]}, {"id": "dalal-kabir-khazana-ibn-ashur", "a": 9, "t": "khilaf", "x": "رجّح ابن عاشور أن «إن أنتم إلا في ضلال كبير» من بقية كلام الخزنة، ويؤيده إعادة فعل القول في «وقالوا لو كنا نسمع» لانقطاع حكاية كلامهم؛ وأجاز أن يكون من كلام الأفواج لرسلهم، والجمع على التوزيع كـ«ركب القوم دوابهم».", "s": ["ibnashur"]}, {"id": "ma-nazzala-anam", "a": 9, "t": "quran", "x": "عموم «من شيء» يدل على أنهم كانوا يحيلون نزول الوحي على بشر، وهذه شنشنة أهل الكفر: ﴿وما قدروا الله حق قدره إذ قالوا ما أنزل الله على بشر من شيء﴾.", "r": "الأنعام: 91", "s": ["ibnashur"]}, {"id": "qasr-qalb-dalal", "a": 9, "t": "balagha", "x": "«إن أنتم إلا في ضلال كبير» قصر قلب: ما حالكم إلا الضلال لا الوحي كما تزعمون؛ والظرفية مجازية لإحاطة الضلال بهم، و«كبير» بمعنى شديد بالغ الغاية.", "s": ["ibnashur"]}, {"id": "zamakhshari-itizal", "a": 9, "t": "aqida", "x": "قال الزمخشري: اعترافهم دليل أنهم لم يُؤتَوا من قدرةٍ كما تزعم المجبرة بل من اختيارهم؛ وعقّب أبو حيان: هو على طريق المعتزلة.", "s": ["bahr"], "n": "قول الزمخشري مبني على أصول المعتزلة في أفعال العباد."}, {"id": "dalal-kabir-rusul-jins", "a": 9, "t": "irab", "x": "إن كان الخطاب في «إن أنتم» للرسل فهو للجنس، ولذا جاء بالجمع مع أن لكل أمة نذيرًا؛ وأجاز الزمخشري أن يكون من كلام الرسل لهم حكوه للخزنة.", "s": ["bahr"]}, {"id": "nadhir-kull-umma", "a": 9, "t": "quran", "x": "اعترفوا بمجيء النذير، كما قال: ﴿وإن من أمة إلا خلا فيها نذير﴾.", "r": "فاطر: 24", "s": ["adwa"]}, {"id": "takdhib-maratib", "a": 9, "t": "balagha", "x": "جمعوا بين تكذيبهم الخاص («فكذبنا») والتكذيب العام («ما نزّل الله من شيء»)، ثم أعلنوا بضلال الرسل، ثم وصفوه بأنه «ضلال كبير»؛ ترقٍّ في العناد والكبر.", "s": ["saadi"]}, {"id": "nadam", "a": 10, "t": "hidaya", "x": "عادوا على أنفسهم بالملامة وندموا حين لا تنفع الندامة: لو كانت لنا عقول ننتفع بها أو أسماع نعي بها الحق ما كنا من أهل النار.", "s": ["ibnkathir"]}, {"id": "aql-kafir", "a": 10, "t": "aqida", "x": "«لو كنا نسمع أو نعقل»: لو كنا نسمع سماع من يعي ويتفكر، أو نعقل عقل من يميّز وينظر؛ ودلّ على أن الكافر لم ينتفع بعقله فكأنه لم يُعطَ منه شيئًا.", "s": ["qurtubi", "baghawi", "ibnjawzi", "bahr", "adwa", "saadi"]}, {"id": "nadim-fajir", "a": 10, "t": "hadith", "x": "«لقد ندم الفاجر يوم القيامة، قالوا: لو كنا نسمع أو نعقل ما كنا في أصحاب السعير».", "r": "عن أبي سعيد الخدري (ذكره القرطبي)", "s": ["qurtubi"]}, {"id": "qalu-majami", "a": 10, "t": "balagha", "x": "أعيد فعل القول «وقالوا» لأنه كلام آخر قالوه في مجامعهم في النار تحسّرًا، كقوله: ﴿قالت أخراهم لأولاهم ربنا هؤلاء أضلونا﴾.", "r": "الأعراف: 38", "s": ["ibnashur"]}, {"id": "aql-mushrikin", "a": 10, "t": "hidaya", "x": "المشركون أقلّ الناس عقلًا لأنهم طرحوا سبب نجاتهم بلا معارض في دينهم، إذ ليس في الشرك وعيد يمنع قبول دعوة الرسل؛ فلولا الإلف والتكبّر لقبلوها، بخلاف أهل الكتاب الذين كانوا إلى المعذرة أقرب.", "s": ["ibnashur"]}, {"id": "kafir-la-aql", "a": 10, "t": "hadith", "x": "حديث: «مَهْ، إن الكافر لا عقل له، أما سمعت قول الله: ﴿وقالوا لو كنا نسمع أو نعقل﴾» – ذكره القرطبي عن الحكيم الترمذي؛ قال ابن عاشور: لم أقف عليه في كتب التفسير، ولم يذكره السيوطي.", "r": "نوادر الأصول (لا يثبت)", "s": ["ibnashur"], "n": "لا يثبت مرفوعًا."}, {"id": "athar-nazar", "a": 10, "t": "hidaya", "x": "قوام الصلاح في حسن التلقي (السمع) وحسن النظر (العقل)؛ فالأثر والنظر أصلا الهدى ﴿الذين يستمعون القول فيتبعون أحسنه﴾؛ و«أو» للتقسيم، وقُدّم السمع لأنه أول ما يتلقاه المنذَر ثم يُعمل عقله.", "r": "الزمر: 18", "s": ["ibnashur"]}, {"id": "sam-aql-jam", "a": 10, "t": "quran", "x": "دفع التعارض: ظاهر «لو كنا نسمع أو نعقل» نفيُ السمع والعقل، وقد قال: ﴿وجعلنا لهم سمعا وأبصارا﴾؛ والجواب أنهم يسمعون ويعقلون ما لا ينفعهم في الآخرة: ﴿ختم الله على قلوبهم وعلى سمعهم﴾، ﴿سمعنا وعصينا﴾، ﴿ولا تكونوا كالذين قالوا سمعنا وهم لا يسمعون﴾.", "r": "الأحقاف: 26؛ البقرة: 7، 93؛ الأنفال: 21", "s": ["ibnashur", "adwa"]}, {"id": "sam-aql", "a": 10, "t": "hidaya", "x": "نفى الكفار عن أنفسهم طريقي الهداية: السمع لما جاءت به الرسل، والعقل النافع؛ وأهل الإيمان أيّدوا إيمانهم بالأدلة السمعية والعقلية معًا.", "s": ["saadi"]}, {"id": "dhanb-mufrad", "a": 11, "t": "irab", "x": "«فاعترفوا بذنبهم»: أُفرد «الذنب» وهو مضاف إلى جمع لأنه في معنى المصدر (الفعل)، فأدّى الواحدُ عن الجمع، كقولهم: خرج عطاءُ الناس.", "s": ["tabari", "qurtubi"]}, {"id": "suhqan", "a": 11, "t": "lugha", "x": "«فسحقا»: فبُعدًا (ابن عباس). وعن سعيد بن جبير: سُحق وادٍ في جهنم. والفصيح تخفيف الحاء، ومن العرب من يضمّها.", "s": ["tabari", "qurtubi", "baghawi", "ibnjawzi", "saadi"]}, {"id": "yudhiru", "a": 11, "t": "hadith", "x": "«لن يهلك الناسُ حتى يُعذِروا من أنفسهم»، وفي حديث آخر: «لا يدخل أحدٌ النار إلا وهو يعلم أن النار أولى به من الجنة»؛ وهو معنى «فاعترفوا بذنبهم».", "r": "مسند أحمد", "s": ["ibnkathir"]}, {"id": "suhqan-qiraa", "a": 11, "t": "qiraat", "x": "قرأ الكسائي وأبو جعفر «فسُحُقًا» بضم الحاء (ورُويت عن علي)، والباقون بالإسكان، وهما لغتان كالسُّحْت والرُّعْب.", "s": ["qurtubi", "baghawi", "ibnashur", "bahr"]}, {"id": "suhqan-irab", "a": 11, "t": "irab", "x": "«سحقا» منصوب على المصدر: أسحقهم الله سحقًا (الزجاج)، والقياس «إسحاقًا» فجاء على حذف الزوائد (أبو علي).", "s": ["qurtubi", "ibnjawzi", "bahr"]}, {"id": "fa-fasiha", "a": 11, "t": "balagha", "x": "الفاء في «فاعترفوا» فصيحة: إذ قالوا ذلك فقد اعترفوا بذنبهم فهم محقوقون بالعذاب؛ والفاء في «فسحقا» للتسبب.", "s": ["ibnashur"]}, {"id": "suhqan-taajjub", "a": 11, "t": "balagha", "x": "«فسحقا»: دعاء بالإبعاد (مفعول مطلق نائب عن فعله)، ويجوز أن يراد التعجب من حالهم كقولهم: قاتله الله؛ واللام للتقوية أو للتبيين كـ«شكرًا لك»، و«أصحاب السعير» عام فهو تذييل.", "s": ["ibnashur"]}, {"id": "suhqan-thulathi", "a": 11, "t": "irab", "x": "لا حاجة لدعوى حذف الزوائد في «سحقا» لأن فعله جاء ثلاثيًّا: «وتسحقه ريح الصبا كل مسحق»؛ وهو دعاء عليهم منصوب بفعل مضمر، بخلاف ما ثبت ووقع فيُرفع كـ﴿ويل للمطففين﴾ (ابن عطية).", "s": ["bahr"]}, {"id": "itiraf-fawat", "a": 11, "t": "aqida", "x": "اعترافهم بذنبهم بعد المعاينة لا ينفع، كإيمان فرعون عند الغرق ﴿آلآن وقد عصيت قبل﴾، و﴿يوم يأتي بعض آيات ربك لا ينفع نفسا إيمانها﴾؛ لأن حقيقة الإيمان التصديق بالغيب، وعليه حديث قبول التوبة «ما لم يغرغر».", "r": "يونس: 90-91؛ الأنعام: 158", "s": ["adwa"]}, {"id": "khashya-ghayb", "a": 12, "t": "tafsir", "x": "«يخشون ربهم بالغيب»: يخافونه وهم لم يروه، فلهم مغفرة لذنوبهم وأجر جزيل على خشيتهم.", "s": ["tabari", "ibnkathir", "qurtubi"]}, {"id": "sabaa-yuzilluhum", "a": 12, "t": "hadith", "x": "شاهد خشية الغيب حديث السبعة الذين يظلهم الله في ظله، ومنهم: «رجل دعته امرأة ذات منصب وجمال فقال: إني أخاف الله»، و«رجل تصدّق بصدقة فأخفاها».", "r": "البخاري 660، مسلم 1031", "s": ["ibnkathir", "bahr"]}, {"id": "bazzar-nifaq", "a": 12, "t": "hadith", "x": "قالوا: يا رسول الله نكون عندك على حال فإذا فارقناك كنا على غيره، قال: «كيف أنتم وربكم؟» قالوا: الله ربنا في السر والعلانية، قال: «ليس ذلكم النفاق». (في إسناده الحارث بن عبيد، له مناكير).", "r": "مسند البزار", "s": ["ibnkathir"]}, {"id": "khashya-qaf", "a": 12, "t": "quran", "x": "نظيرها: ﴿من خشي الرحمن بالغيب وجاء بقلب منيب﴾.", "r": "ق: 33", "s": ["qurtubi"]}, {"id": "ajr-janna", "a": 12, "t": "tafsir", "x": "«وأجر كبير»: هو الجنة.", "s": ["qurtubi", "ibnjawzi"]}, {"id": "targhib-tarhib", "a": 12, "t": "munasaba", "x": "على سنن القرآن في تعقيب الرهبة بالرغبة: لما ذكر ما أعدّ للكافرين أعقبه بما أعدّ للذين يخشون ربهم بالغيب.", "s": ["ibnashur"]}, {"id": "taqdim-maghfira", "a": 12, "t": "balagha", "x": "قُدّمت المغفرة على الأجر تطمينًا لقلوبهم لخشيتهم المؤاخذة على ما فرط منهم، جريًا على قاعدة تقديم التخلية على التحلية ودفع الضر على جلب النفع؛ وتنكير «مغفرة» للتعظيم.", "s": ["ibnashur"]}, {"id": "khashya-ghayb-maad", "a": 12, "t": "khilaf", "x": "«بالغيب»: إما ما أُخبروا به من أمر المعاد وأحواله، وإما غائبين عن أعين الناس في خلواتهم، كحديث: «ورجلٌ ذكر الله خاليًا ففاضت عيناه».", "s": ["bahr"]}, {"id": "khashya-ulama", "a": 12, "t": "quran", "x": "الخشية شدة الخوف، ومحلها العلماء: ﴿إنما يخشى الله من عباده العلماء﴾، ونظيرها: ﴿الذين يخشون ربهم بالغيب وهم من الساعة مشفقون﴾، و﴿من خشي الرحمن بالغيب وجاء بقلب منيب﴾.", "r": "فاطر: 28؛ الأنبياء: 49؛ ق: 33", "s": ["adwa"]}, {"id": "khashya-ghayb-ihsan", "a": 12, "t": "hadith", "x": "الغيب هنا من جهة العبد لا من جهة الرب، كحديث الإحسان: «أن تعبد الله كأنك تراه، فإن لم تكن تراه فإنه يراك»، وهو أقوى عامل على اكتساب الخشية.", "r": "حديث جبريل (مسلم)", "s": ["adwa"]}, {"id": "khashya-asas", "a": 12, "t": "hidaya", "x": "خشية الله بالغيب والإيمان بالغيب أساس عمل المسلم ومعاملاته؛ والعرب تمدح من خلوته كمشهده: «يتجنب الهفوات في خلواته ... عفّ السريرة غيبُه كالمشهدِ»؛ وإفراد الله بالخشية منزلة الأنبياء ﴿ولا يخشون أحدا إلا الله﴾.", "r": "الأحزاب: 39", "s": ["adwa"]}, {"id": "muqabala-abrar", "a": 12, "t": "munasaba", "x": "لما ذكر حال الأشقياء الفجار ذكر وصف الأبرار السعداء: «إن الذين يخشون ربهم بالغيب»، على طريقة القرآن في المقابلة بين الفريقين.", "s": ["saadi"]}, {"id": "khashya-ghayb-saadi", "a": 12, "t": "hidaya", "x": "«بالغيب»: في جميع أحوالهم حتى حين لا يطّلع عليهم إلا الله، فلا يُقدمون على معصية ولا يقصّرون في طاعة.", "s": ["saadi"]}, {"id": "ajr-kabir-rida", "a": 12, "t": "aqida", "x": "«أجر كبير»: نعيم الجنة المقيم والملك الكبير، وأعظم من ذلك رضا الرحمن الذي يُحلّه على أهل الجنان.", "s": ["saadi"]}, {"id": "dhat-sudur", "a": 13, "t": "aqida", "x": "من لا يخفى عليه ما في الضمائر مما لم يُتكلّم به، فأحرى ألا يخفى عليه ما نُطق به سرًّا أو جهرًا.", "s": ["tabari", "ibnkathir", "saadi"]}, {"id": "asirru-nuzul", "a": 13, "t": "nuzul", "x": "ابن عباس: نزلت في المشركين؛ كانوا ينالون من النبي ﷺ فيخبره جبريل، فقال بعضهم لبعض: أسِرّوا قولكم كي لا يسمع ربُّ محمد، فنزلت: ﴿وأسروا قولكم أو اجهروا به﴾.", "r": "ابن عباس", "s": ["qurtubi", "baghawi", "ibnjawzi", "ibnashur", "bahr"]}, {"id": "asirru-amr-khabar", "a": 13, "t": "balagha", "x": "«وأسروا قولكم أو اجهروا به»: لفظه أمر ومعناه الخبر، أي: إن أخفيتم أو أعلنتم فهو عليم بذات الصدور.", "s": ["qurtubi"]}, {"id": "dhat-sudur-lugha", "a": 13, "t": "lugha", "x": "«ذات الصدور»: ما فيها من خير وشر، كما يُسمّى الجنين «ذا بطنها».", "s": ["qurtubi"]}, {"id": "rujua-kuffar", "a": 13, "t": "munasaba", "x": "بعد ذكر جزاء أهل الخشية عاد إلى خطاب الكفار فقال: «وأسروا قولكم أو اجهروا به».", "s": ["ibnjawzi"]}, {"id": "asirru-taswiya", "a": 13, "t": "balagha", "x": "صيغة الأمر «أسرّوا... أو اجهروا» مستعملة في التسوية كقوله ﴿اصبروا أو لا تصبروا﴾، وهو غالب «افعل» إذا عُطف عليها نقيضها بـ«أو»؛ و«إنه عليم بذات الصدور» تعليل للتسوية.", "r": "الطور: 16", "s": ["ibnashur"]}, {"id": "dhat-sudur-ibn-ashur", "a": 13, "t": "lugha", "x": "«ذات الصدور»: ما يتردد في النفس من الخواطر والنوايا؛ و«ذات» مؤنث «ذو» بمعنى صاحب، والصدور بمعنى العقول.", "s": ["ibnashur"]}, {"id": "sirr-jahr-raad", "a": 13, "t": "quran", "x": "السر والجهر عند الله سواء: ﴿سواء منكم من أسر القول ومن جهر به﴾، ﴿وإن تجهر بالقول فإنه يعلم السر وأخفى﴾، ﴿ونعلم ما توسوس به نفسه﴾.", "r": "الرعد: 10؛ طه: 7؛ ق: 16", "s": ["adwa"]}, {"id": "munasaba-tahrim", "a": 13, "t": "munasaba", "x": "تقدّم في سورة التحريم قبلها مباشرة: ﴿وإذ أسرّ النبي إلى بعض أزواجه حديثا... قال نبأني العليم الخبير﴾، وهو بيان عملي مشاهد أنه يعلم السر وأخفى؛ ولذا قال هنا: «ألا يعلم من خلق وهو اللطيف الخبير».", "s": ["adwa"]}, {"id": "ala-yalam", "a": 14, "t": "aqida", "x": "«ألا يعلم من خلق»: كيف يخفى على الخالق خلقُه الذي خلق؟ وهو اللطيف بعباده الخبير بأعمالهم.", "s": ["tabari"]}, {"id": "ala-yalam-khilaf", "a": 14, "t": "irab", "x": "«من خلق»: الأَوْلى أنّ «مَن» فاعل، أي: ألا يعلم الخالقُ؟ وقيل مفعول: ألا يعلم اللهُ مخلوقَه؟ ورجّح الأول بدلالة قوله: ﴿وهو اللطيف الخبير﴾.", "s": ["ibnkathir", "qurtubi", "baghawi", "ibnashur", "bahr"]}, {"id": "ala-yalam-sirr", "a": 14, "t": "aqida", "x": "«ألا يعلم من خلق»: ألا يعلم السرَّ من خلق السرّ؟ ولا بد أن يكون الخالق عالمًا بما خلق وما يخلق.", "s": ["qurtubi", "ibnjawzi"]}, {"id": "ibn-musayyib-waraq", "a": 14, "t": "athar", "x": "ابن المسيّب: وقف رجل في شجر كثير وقد عصفت الريح فوقع في نفسه: أترى الله يعلم ما يسقط من هذا الورق؟ فنودي: ﴿ألا يعلم من خلق وهو اللطيف الخبير﴾.", "r": "سعيد بن المسيب", "s": ["qurtubi"]}, {"id": "asmaa-ilm", "a": 14, "t": "aqida", "x": "من أسماء صفات العلم: العليم (يعمّ المعلومات)، والخبير (يعلم ما يكون قبل أن يكون)، والحكيم (دقائق الأوصاف)، والشهيد (الغائب والحاضر)، والحافظ (لا ينسى)، والمحصي (لا تشغله الكثرة)؛ ذكره أبو إسحاق الإسفراييني.", "s": ["qurtubi", "adwa"]}, {"id": "latif-khabir", "a": 14, "t": "aqida", "x": "«اللطيف»: لطيف علمه بما في القلوب، «الخبير»: بما فيها من الخير والشر والوسوسة.", "s": ["baghawi"]}, {"id": "ala-yalam-istinaf", "a": 14, "t": "balagha", "x": "«ألا يعلم من خلق» استئناف بياني جوابًا لمن يسأل: كيف يعلم ما في الصدور وما في نفس المرء لا يعلمه غيره؟ فأُجيب: إنه خالق أصحاب تلك الصدور؛ والموصول يفيد التعليل بالصلة.", "s": ["ibnashur"]}, {"id": "ilm-la-afal", "a": 14, "t": "aqida", "x": "قال ابن عاشور: الآية دليل على عموم علمه تعالى، ولا دلالة فيها على أنه خالق أفعال العباد للانفكاك بين تعلّق العلم وتعلّق القدرة.", "s": ["ibnashur"]}, {"id": "latif-khabir-ibn-ashur", "a": 14, "t": "aqida", "x": "«اللطيف»: العالم بخبايا الأمور المدبّر لها برفق وحكمة، «الخبير»: العليم الذي لا تعزب عنه الحوادث الخفية، مشتق من الخبر.", "s": ["ibnashur"]}, {"id": "ala-yalam-mafool", "a": 14, "t": "khilaf", "x": "«مَن» في «ألا يعلم من خلق»: أجازوا الفاعلية والمفعولية، والذي تشهد له النصوص عند صاحب الأضواء أنها مفعول، لقوله: ﴿والله خلقكم وما تعملون﴾؛ ومن أعمالهم ما يسرّون وما يجهرون.", "r": "الصافات: 96", "s": ["bahr", "adwa"]}, {"id": "ala-yalam-aqli", "a": 14, "t": "aqida", "x": "«ألا يعلم من خلق» دليل عقلي على العلم: من خلق الخلق وأتقنه وأحسنه كيف لا يعلمه؟!", "s": ["saadi"]}, {"id": "latif-saadi", "a": 14, "t": "aqida", "x": "من معاني «اللطيف»: الذي لطف علمه حتى أدرك السرائر والخفايا، والذي يلطف بعبده فيسوق إليه البرّ من حيث لا يشعر، ويعصمه من الشر من حيث لا يحتسب، وقد يذيقه المكاره ليوصله بها إلى المحابّ الجليلة.", "s": ["saadi"]}, {"id": "latif-taha", "a": 14, "t": "quran", "x": "نظيرها في سعة العلم: ﴿فإنه يعلم السر وأخفى﴾.", "r": "طه: 7", "s": ["saadi"]}, {"id": "manakib", "a": 15, "t": "khilaf", "x": "«مناكبها»: قيل جبالها (ابن عباس في رواية، قتادة)، وقيل أطرافها ونواحيها وطرقها (ابن عباس في رواية، مجاهد). ورجّح الطبري: نواحيها وجوانبها، تشبيهًا بمناكب الإنسان التي هي أطرافه.", "s": ["tabari", "ibnkathir", "qurtubi", "baghawi", "ibnjawzi"]}, {"id": "bashir-jariya", "a": 15, "t": "athar", "x": "قصة بشير بن كعب: قال لجاريته إن عرفتِ معنى «مناكبها» فأنت حرة، فقالت: جبالها، فأراد أن يتزوجها فاستفتى أبا الدرداء فقال: الخير في طمأنينة والشر في ريبة، فدع ما يريبك إلى ما لا يريبك.", "r": "قتادة عن بشير بن كعب", "s": ["tabari", "ibnkathir", "qurtubi"]}, {"id": "nushur", "a": 15, "t": "tafsir", "x": "«وإليه النشور»: إلى الله نشرُكم من قبوركم؛ فالمشي في الأرض والأكل من رزقها ينتهي إلى البعث.", "s": ["tabari", "baghawi", "ibnjawzi"]}, {"id": "ard-dhalul", "a": 15, "t": "tafsir", "x": "ذلّل الأرض: جعلها قارّة ساكنة لا تميد ولا تضطرب بما أرساه فيها من الجبال، وأنبع العيون وسلك السُّبُل وهيّأ المنافع والزروع.", "s": ["ibnkathir", "qurtubi"]}, {"id": "sabab-tawakkul", "a": 15, "t": "hidaya", "x": "«فامشوا في مناكبها وكلوا من رزقه»: السعي في الأسباب لا ينافي التوكل، فالسعي لا يجدي إلا أن ييسّره الله.", "s": ["ibnkathir"]}, {"id": "tayr-tawakkul", "a": 15, "t": "hadith", "x": "«لو أنكم تتوكلون على الله حق توكله لرزقكم كما يرزق الطير، تغدو خِماصًا وتروح بِطانًا»؛ فأثبت لها غدوًّا ورواحًا لطلب الرزق مع توكلها.", "r": "أحمد، الترمذي 2344 (حسن صحيح)، ابن ماجه 4164", "s": ["ibnkathir"]}, {"id": "dhalul-lugha", "a": 15, "t": "lugha", "x": "«ذلولا»: سهلة منقادة لا تمتنع بالحزونة والغلظة؛ والذِّلّ: اللين والانقياد. وقيل: ثبّتها بالجبال، وقيل: مكّن فيها الزرع والغرس وحفر الآبار.", "s": ["qurtubi", "baghawi", "ibnjawzi"]}, {"id": "amr-ibaha", "a": 15, "t": "ahkam", "x": "«فامشوا» أمر إباحة فيه إظهار الامتنان، وقيل: خبر بلفظ الأمر؛ و«كلوا من رزقه»: مما أحله لكم (الحسن).", "s": ["qurtubi", "adwa"]}, {"id": "manakib-asl", "a": 15, "t": "lugha", "x": "أصل المنكب الجانب، ومنه منكب الرجل، والريح النكباء، وتنكّب عن الشيء.", "s": ["qurtubi", "baghawi"]}, {"id": "nushur-qudra", "a": 15, "t": "munasaba", "x": "«وإليه النشور»: الذي خلق السماء بلا تفاوت وذلّل الأرض قادر على أن ينشركم؛ فربط دليل الخلق بالبعث.", "s": ["qurtubi"]}, {"id": "manakib-aqwal", "a": 15, "t": "khilaf", "x": "أقوال السلف في «مناكبها»: جبالها (ابن عباس وقتادة)، آكامها (الضحاك)، طرقها وفجاجها (مجاهد)، سُبُلها (الحسن)، أطرافها (الكلبي)، نواحيها (مقاتل)، جوانبها (الفراء).", "s": ["baghawi"]}, {"id": "manakib-zajjaj", "a": 15, "t": "khilaf", "x": "في «مناكبها» ثلاثة أقوال: طرقاتها (ابن عباس برواية العوفي، ومجاهد)، جبالها (ابن عباس برواية ابن أبي طلحة، وقتادة، واختاره الزجاج لأنه إذا سهّل السلوك في جبالها فهو أبلغ في التذليل)، جوانبها (مقاتل والفراء وأبو عبيدة، واختاره ابن قتيبة).", "s": ["ibnjawzi", "bahr"]}, {"id": "ard-dalil", "a": 15, "t": "munasaba", "x": "خلق الأرض أدل على القدرة والعلم من خلق الإنسان إذ هو جزء منها ﴿منها خلقناكم﴾؛ فلما استدل بخلق أنفسهم شفعه بخلق الأرض مع المنّة بتذليلها.", "s": ["ibnashur"]}, {"id": "dhalul-istiara", "a": 15, "t": "balagha", "x": "استُعير «الذلول» (الدابة المنقادة) للأرض، و«المناكب» ترشيح، و«فامشوا» كركوبها، و«كلوا من رزقه» كالأكل من ألبان الذلول ونتاجها؛ وجمع «المناكب» تجريد للاستعارة إذ للدابة منكبان وللأرض متّسعات كثيرة.", "s": ["ibnashur"]}, {"id": "amr-idama", "a": 15, "t": "ahkam", "x": "الأمر في «فامشوا» و«كلوا» مستعمل في معنى الإدامة للتذكير والامتنان، ليتدبروا فيتركوا العناد ﴿كذلك يتم نعمته عليكم لعلكم تسلمون﴾.", "r": "النحل: 81", "s": ["ibnashur"]}, {"id": "nushur-qasr", "a": 15, "t": "balagha", "x": "«وإليه النشور» تتميم لمناسبة الأرض لأنها مثوى الناس بعد الموت، والتقدير: وفيها تعودون ومنها النشور إليه؛ وتعريف الطرفين في «هو الذي جعل» قصر قلب تنزيلًا لهم منزلة من يعتقد أن الأصنام خلقتها.", "s": ["ibnashur"]}, {"id": "dhalul-qasir", "a": 15, "t": "irab", "x": "«ذلول» فعول للمبالغة، وردّ أبو حيان قول ابن عطية إنه بمعنى مفعول (مذلولة كركوب وحلوب) لأن فعله «ذلّ» قاصر لا يتعدى إلا بالهمزة ﴿وتذل من تشاء﴾ أو التضعيف ﴿وذللناها لهم﴾.", "s": ["bahr"]}, {"id": "manakib-bair", "a": 15, "t": "balagha", "x": "الزمخشري: المشي في مناكبها مثلٌ لفرط التذليل؛ لأن المنكبين وملتقاهما من الغارب أرقّ شيء من البعير وأبعده عن أن يطأه الراكب، فإذا ذُلّلت حتى يُمشى في مناكبها لم يبق شيء لم يُذلَّل.", "s": ["bahr"]}, {"id": "nushur-shukr", "a": 15, "t": "hidaya", "x": "«وإليه النشور»: البعث، فيسألكم عن شكر هذه النعمة.", "s": ["bahr"]}, {"id": "dhalul-mubalagha", "a": 15, "t": "lugha", "x": "«ذلول» فعول بمعنى مفعول للمبالغة في الذل؛ وتذليلها: تثبيتها بالجبال ﴿والجبال أرساها متاعا لكم﴾، وتمكين الزرع ﴿فأنبتنا فيها حبا﴾.", "r": "النازعات: 32-33؛ عبس: 27", "s": ["adwa"]}, {"id": "kifat", "a": 15, "t": "quran", "x": "كان الشنقيطي يقول: من تسخيرها أن جعلها كفاتًا للإنسان حيًّا على ظهرها وميتًا في بطنها: ﴿ألم نجعل الأرض كفاتا أحياء وأمواتا﴾؛ ولو شاء لجعلها حديدًا ونحاسًا فلا يحرث ولا يبني ولا يجد مدفنًا.", "r": "المرسلات: 25-26", "s": ["adwa"]}, {"id": "saay-istithmar", "a": 15, "t": "hidaya", "x": "الأمر بالمشي في المناكب للإباحة، لكن تقديم الامتنان بالتذليل حثٌّ للأمة على السعي والعمل والإنتاج حتى تستغني عن غيرها؛ وقال النووي: على الأمة أن تنتج كل حاجياتها حتى الإبرة.", "s": ["adwa"]}, {"id": "taskhir-shukr", "a": 15, "t": "quran", "x": "من رأى التسخير اعترف بالفضل وشكر: ﴿كذلك سخرناها لكم لعلكم تشكرون﴾، ﴿سبحان الذي سخر لنا هذا... وإنا إلى ربنا لمنقلبون﴾.", "r": "الحج: 36؛ الزخرف: 13-14", "s": ["adwa"]}, {"id": "nushur-jumua", "a": 15, "t": "munasaba", "x": "«وإليه النشور» بعد المشي وطلب الرزق: فالمشي في الأرض ليس لطلب الرزق وحده، بل للأخذ بالأسباب والاعتبار بالمخلوقات والتزوّد لما بعد الممات، كقوله: ﴿فانتشروا في الأرض وابتغوا من فضل الله واذكروا الله كثيرا﴾.", "r": "الجمعة: 10", "s": ["adwa"]}, {"id": "ard-taskhir", "a": 15, "t": "hidaya", "x": "ذلّل الأرض لتدركوا منها كل حاجة من غرس وبناء وحرث وطرق إلى الأقطار النائية؛ و«فامشوا في مناكبها» لطلب الرزق والمكاسب.", "s": ["saadi"]}, {"id": "dunya-bulgha", "a": 15, "t": "hidaya", "x": "«وإليه النشور»: الدنيا دار امتحان وبُلغة يُتبلّغ بها إلى الآخرة، ثم تُبعثون لتُجازَوا بأعمالكم.", "s": ["saadi"]}, {"id": "man-fis-samaa", "a": 16, "t": "aqida", "x": "«أأمنتم من في السماء»: هو الله تعالى، يتوعّد الكافرين أن يخسف بهم الأرض فإذا هي تمور: تذهب وتجيء وتضطرب.", "s": ["tabari", "ibnkathir", "qurtubi", "ibnjawzi", "adwa", "saadi"]}, {"id": "hilm-tamhil", "a": 16, "t": "aqida", "x": "من لطفه أنه قادر على تعذيبهم بكفرهم، ومع ذلك يحلم ويؤجّل ولا يعجّل، كما قال: ﴿ولو يؤاخذ الله الناس بما كسبوا ما ترك على ظهرها من دابة﴾.", "r": "فاطر: 45", "s": ["ibnkathir"]}, {"id": "man-fis-samaa-khilaf", "a": 16, "t": "khilaf", "x": "«من في السماء»: قيل عذابُ من في السماء، وقيل قدرته وسلطانه وعرشه، وخصّ السماء تنبيهًا على أن الإله من نفذت قدرته في السماء لا من يعظّمونه في الأرض، وقيل: الملائكة أو جبريل الموكل بالعذاب.", "s": ["qurtubi", "baghawi", "bahr"]}, {"id": "uluw", "a": 16, "t": "aqida", "x": "قال المحققون: «في السماء» أي فوقها كقوله ﴿فسيحوا في الأرض﴾، والأخبار في العلوّ كثيرة صحيحة لا يدفعها إلا ملحد أو جاهل معاند؛ والسماء قبلة الدعاء لأنها مهبط الوحي ومنزل القطر وإليها تُرفع الأعمال وفوقها العرش.", "s": ["qurtubi", "adwa"]}, {"id": "tamur", "a": 16, "t": "lugha", "x": "«تمور»: تذهب وتجيء؛ والمَوْر: الاضطراب بالذهاب والمجيء، وإذا خُسف بإنسان دارت به الأرض.", "s": ["qurtubi", "baghawi", "ibnashur", "bahr"]}, {"id": "aamintum-qiraa", "a": 16, "t": "qiraat", "x": "«أأمنتم»: قرأ قنبل عن ابن كثير بإبدال الهمزة الأولى واوًا في الوصل «النشورُ وَأَمنتم»، وحقّق الهمزتين الكوفيون والبصريون وأهل الشام سوى أبي عمرو وهشام، وسهّل الباقون.", "s": ["qurtubi", "ibnjawzi", "bahr", "adwa"]}, {"id": "tamur-khasf", "a": 16, "t": "tafsir", "x": "«تمور»: تتحرك بأهلها (الحسن)؛ والمعنى أن الله يحرّك الأرض عند الخسف حتى تلقيهم إلى أسفل وتعلو عليهم.", "s": ["baghawi"]}, {"id": "aamintum-qiraa-jawzi", "a": 16, "t": "qiraat", "x": "تفصيل «أأمنتم»: ابن كثير «النشورُ وَامنتم»، ونافع وأبو عمرو «آمنتم» بهمزة ممدودة، وعاصم وابن عامر وحمزة والكسائي «أأمنتم» بهمزتين.", "s": ["ibnjawzi"]}, {"id": "tamur-tadur", "a": 16, "t": "tafsir", "x": "«تمور»: تدور، قال مقاتل: تدور بكم إلى الأرض السفلى.", "s": ["ibnjawzi"]}, {"id": "istidlal-takhwif", "a": 16, "t": "munasaba", "x": "انتقال من الاستدلال إلى التخويف: لما تقرر أنه خالق الأرض ومذلّلها وأنهم لم يرعوه حق رعايته، استحقوا أن يصير مشيهم في مناكبها تجلجلًا في طبقاتها.", "s": ["ibnashur"]}, {"id": "man-fis-samaa-ibn-ashur", "a": 16, "t": "khilaf", "x": "ذكر ابن عاشور في «من في السماء» طريقتي التفويض للسلف والتأويل للخلف، وأجاز أن يراد به الملائكة الموكلون بالخسف وإسناد الخسف إليهم حقيقة ﴿إنا مهلكو أهل هذه القرية﴾؛ وجمهور السلف على أن المراد الله تعالى (انظر الطبري والأضواء).", "r": "العنكبوت: 31", "s": ["ibnashur"], "n": "مذهب السلف إثبات العلوّ لا التفويض في المعنى."}, {"id": "khasf-zilzal", "a": 16, "t": "lugha", "x": "الخسف: انقلاب ظاهر بعض الأرض باطنًا وباطنه ظاهرًا وهو شدة الزلزال؛ والباء في «بكم» للمصاحبة؛ وفي الجمع بين السماء والأرض محسّن الطباق.", "s": ["ibnashur"]}, {"id": "fa-idha-mufajaa", "a": 16, "t": "balagha", "x": "«فإذا هي تمور»: «إذا» الفجائية تنزّل الخسف المتوعَّد به منزلة الواقع الحاصل تحقيقًا له، كقوله ﴿إذا أنتم تخرجون﴾؛ فهي تمثيلية مكنية.", "s": ["ibnashur"]}, {"id": "aamintum-qiraa-bahr", "a": 16, "t": "qiraat", "x": "«أأمنتم»: نافع وأبو عمرو والبزي بتحقيق الأولى وتسهيل الثانية، وأدخل أبو عمرو وقالون ألفًا بينهما، وقنبل بإبدال الأولى واوًا، والكوفيون وابن عامر بتحقيقهما.", "s": ["bahr"]}, {"id": "man-fis-samaa-tawil", "a": 16, "t": "khilaf", "x": "ذهب أبو حيان إلى التأويل: «من في السماء» مجاز عن ملكوته، أو على معتقدهم، أو الملائكة، أو جبريل، أو بمعنى العلوّ بالقهر؛ وخالفه السلف فأثبتوا العلوّ على ظاهره (انظر الطبري والقرطبي والأضواء).", "s": ["bahr"], "n": "هذا تأويل أشعري؛ ومذهب السلف إثبات العلوّ على ظاهره بلا تكييف (انظر قول الطبري وأضواء البيان)."}, {"id": "khasf-qarun", "a": 16, "t": "tafsir", "x": "الخسف: ذهاب الأرض سُفلًا كما خُسف بقارون، والمور: الحركة المضطربة السريعة، وقد ثبّتها الله بالجبال أوتادًا.", "s": ["adwa"]}, {"id": "uluw-jariya", "a": 16, "t": "aqida", "x": "«من في السماء» هو الله كما قال ابن جرير وعزاه القرطبي لابن عباس، ويشهد له أن الخسف وإرسال الحاصب لا يقدر عليه إلا الله؛ وهو معتقد السلف لحديث الجارية: «أين الله؟» قالت: في السماء، قال: «أعتقها فإنها مؤمنة»؛ وردٌّ على من تأوّله بالملكوت أو جبريل فرارًا من صفة العلو.", "r": "مسلم (حديث الجارية)", "s": ["adwa"]}, {"id": "fi-zarfiyya", "a": 16, "t": "aqida", "x": "ليست «في» للظرفية المعهودة في المخلوق؛ فالسماوات في الكرسي كحلقة في فلاة، والكرسي في العرش كذلك، وهو سبحانه مستوٍ على عرشه؛ فـ«في السماء» بمعنى فوقها أو عليها، والمراد العلوّ.", "s": ["adwa"]}, {"id": "hasib", "a": 17, "t": "lugha", "x": "«حاصبا»: ريح فيها التراب والحصباء الصغار.", "s": ["tabari", "ibnkathir"]}, {"id": "hasib-isra", "a": 17, "t": "quran", "x": "نظيرها: ﴿أفأمنتم أن يخسف بكم جانب البر أو يرسل عليكم حاصبا ثم لا تجدوا لكم وكيلا﴾.", "r": "الإسراء: 68", "s": ["ibnkathir"]}, {"id": "hasib-qurtubi", "a": 17, "t": "tafsir", "x": "«حاصبا»: حجارة من السماء كما أُرسلت على قوم لوط وأصحاب الفيل، وقيل: ريح فيها حصباء، وقيل: سحاب فيه حجارة.", "s": ["qurtubi", "baghawi", "ibnjawzi"]}, {"id": "nadhir-munzir", "a": 17, "t": "khilaf", "x": "«كيف نذير»: أي إنذاري، وقيل: النذير هو المنذِر محمد ﷺ، فستعلمون صدقه وعاقبة تكذيبكم.", "s": ["qurtubi"]}, {"id": "am-idrab", "a": 17, "t": "balagha", "x": "«أم» للإضراب الانتقالي: الاستفهام الأول إنكار أمنهم عقوبة أرضية، والثاني إنكار أمنهم عقوبة سماوية وهي أشدّ وقعًا؛ وقُدّم الخسف لأن الكلام في أحوال الأرض، والحاصب جزاء كفرهم بالرزق الذي منشؤه السماء ﴿وفي السماء رزقكم﴾.", "r": "الذاريات: 22", "s": ["ibnashur"]}, {"id": "fasatalamun-tahdid", "a": 17, "t": "balagha", "x": "«فستعلمون كيف نذير»: السين للمستقبل، والمهدَّد به ليس خبرًا واقعًا لا محالة (فقد يؤمنون فيسلمون) بل تهديد نُزّل منزلة الواقع؛ و«كيف» استفهام تهويل؛ وحُذفت ياء «نذيري» تخفيفًا ورعيًا للفاصلة.", "s": ["ibnashur"]}, {"id": "nadhir-nakir-masdar", "a": 17, "t": "lugha", "x": "«نذير» و«نكير» مصدران بمعنى الإنذار والإنكار، ومنه قول حسان: «فأنذر مثلها نصحًا قريشًا ... من الرحمن إن قبلت نذيرا».", "s": ["ibnashur", "bahr"]}, {"id": "amn-makr", "a": 17, "t": "hidaya", "x": "لا تحسبوا أن أمنكم من عقاب الله من الأرض ومن السماء ينفعكم؛ فمن قبلكم كذّبوا فعاجلهم الله بالعقوبة الدنيوية قبل الأخروية.", "s": ["saadi"]}, {"id": "nakir", "a": 18, "t": "tafsir", "x": "«فكيف كان نكير»: فكيف كان إنكاري على الأمم الخالية تكذيبهم رسلهم؟ تهديد لقريش بمصير من سبقهم.", "s": ["tabari", "ibnkathir", "baghawi", "ibnjawzi"]}, {"id": "umam-mukadhdhiba", "a": 18, "t": "tafsir", "x": "«الذين من قبلهم»: كقوم نوح وعاد وثمود وقوم لوط وأصحاب مدين وأصحاب الرس وقوم فرعون.", "s": ["qurtubi"]}, {"id": "nakir-qiraa", "a": 18, "t": "qiraat", "x": "أثبت ورش الياء في «نذيري» و«نكيري» وصلًا، ويعقوب في الحالين، وحذفها الباقون اتباعًا للمصحف.", "s": ["qurtubi", "bahr"]}, {"id": "iltifat-ghayba", "a": 18, "t": "balagha", "x": "التفات من الخطاب إلى الغيبة في «ولقد كذب الذين من قبلهم» (ولم يقل: من قبلكم) تعريضًا بالغضب عليهم وإبعادًا لهم عن شرف الخطاب.", "s": ["ibnashur"]}, {"id": "qiyas-tamthil", "a": 18, "t": "hidaya", "x": "ضرب لهم المثل بالأمم المكذبة ليتّعظوا بقياس التمثيل إن لم تبلغ عقولهم الانتفاع بأقيسة الاستنتاج، فالعرب عرفوا آثار عاد وثمود وأخبار قوم نوح ولوط وأصحاب الرس؛ وأُكّد الخبر باللام و«قد».", "s": ["ibnashur"]}, {"id": "tayr-saffat", "a": 19, "t": "lugha", "x": "«صافّات ويقبضن»: تبسط أجنحتها أحيانًا وتقبضها أحيانًا (قتادة، مجاهد).", "s": ["tabari", "ibnkathir", "qurtubi", "baghawi", "ibnjawzi"]}, {"id": "tayr-tawhid", "a": 19, "t": "hidaya", "x": "إمساك الطير في الجو بلا عَمَد آيةٌ لمن اعتبر، يعلم بها أن ربه واحد لا شريك له، وأنه بصير لا يدخل تدبيرَه خلل.", "s": ["tabari", "saadi"]}, {"id": "tayr-nahl", "a": 19, "t": "quran", "x": "نظيرها: ﴿ألم يروا إلى الطير مسخرات في جو السماء ما يمسكهن إلا الله﴾.", "r": "النحل: 79", "s": ["ibnkathir", "adwa"]}, {"id": "tayr-dhallal", "a": 19, "t": "munasaba", "x": "كما ذلّل الأرض للآدمي ذلّل الهواء للطير؛ فناسب ذكر الطير بعد ذكر الأرض الذلول.", "s": ["qurtubi"]}, {"id": "yaqbidna-irab", "a": 19, "t": "irab", "x": "«ويقبضن» فعل مضارع معطوف على اسم الفاعل «صافات»، وهو جائز كعطف الاسم على المضارع في قول الشاعر: «يقصد في أسوقها وجائر».", "s": ["qurtubi", "bahr"]}, {"id": "tayr-imsak-halayn", "a": 19, "t": "tafsir", "x": "«ما يمسكهن»: في حال القبض والبسط أن يسقطن إلا الرحمن.", "s": ["baghawi"]}, {"id": "tayr-tayaran", "a": 19, "t": "lugha", "x": "بسط الجناح ثم قبضه بعد البسط هو حقيقة الطيران.", "s": ["ibnjawzi"]}, {"id": "tayr-itnab", "a": 19, "t": "balagha", "x": "أطنب هنا في وصف الطير («فوقهم، صافات، ويقبضن») بخلاف آية النحل ﴿مسخرات في جو السماء﴾ (وهي أسبق نزولًا)؛ لأنهم لم يتفطنوا لها فزيدوا تصويرًا؛ والإلف يُذهب العجب، كمن يرى الفيل أو البحر لأول مرة.", "r": "النحل: 79", "s": ["ibnashur"]}, {"id": "rahman-arba", "a": 19, "t": "balagha", "x": "إيثار اسم «الرحمن» هنا دون «الله» (كما في النحل) لأنهم أنكروا اسم الرحمن، فذُكر في هذه السورة أربع مرات.", "s": ["ibnashur"]}, {"id": "tayr-najat", "a": 19, "t": "munasaba", "x": "إيماء: الذي أمسك الطير عن الهويّ هو الذي أهلك الأمم قبلهم، فلو أطاعوه لأنجاهم من الهلاك كما أنجى الطير من السقوط.", "s": ["ibnashur"]}, {"id": "tayr-khasais", "a": 19, "t": "hidaya", "x": "إمساك الطير بما أودع في خلقتها من خفة العظام وقوة الجوانح والقوادم والخوافي وشكل الأجساد النافذ في الهواء؛ وكل ذلك بخلق الله، لا بمعاليق كما يعلّق المشعوذ الصور بخيوط خفية.", "s": ["ibnashur"]}, {"id": "basir-alim", "a": 19, "t": "lugha", "x": "«بصير» هنا بمعنى العليم من البصيرة (كقولهم: فلان بصير بالأمور)، لا الاسم الحسن المقرون بالسميع؛ وتقديم «بكل شيء» قصر قلب ردًّا على من زعم أنه لا يعلم كل شيء.", "s": ["ibnashur"]}, {"id": "tayr-fil", "a": 19, "t": "munasaba", "x": "مناسبة ذكر الطير بعد الحاصب: أن الله أهلك أصحاب الفيل بالطير والحجارة التي رمتهم بها؛ ففيه تذكير لقريش بهذه القصة، وأنه لو شاء لأهلكهم بحاصب ترمي به الطير.", "s": ["bahr"]}, {"id": "ism-fil-adiyat", "a": 19, "t": "irab", "x": "عطف الفعل على الاسم لأنه في معناه فصيح، كقوله: ﴿فالمغيرات صبحا فأثرن به نقعا﴾، وعكسه جائز إلا عند السهيلي.", "s": ["bahr"]}, {"id": "tayr-tabia", "a": 19, "t": "aqida", "x": "ردّ أبو حيان على الزمخشري نزوعه إلى قول أهل الطبيعة في تعليل الطيران بشكل الأجسام: فالله إذا أراد إمساك أثقل الأشياء في الهواء كان، وليس ذلك معلّقًا بشكل ولا ثقل ولا خفة؛ وإنما «ما يمسكهن إلا الرحمن» بقدرته.", "s": ["bahr"]}, {"id": "saffat-ism-fil", "a": 19, "t": "balagha", "x": "عطف الفعل «ويقبضن» على الاسم «صافات» ولم يقل «قابضات» لأن الأصل في الطيران بسط الجناح والقبض طارئ (أبو حيان)؛ فالاسم للدوام والثبوت والفعل للتجدد والحدوث.", "s": ["ibnashur", "bahr", "adwa"]}, {"id": "imsak-samawat", "a": 19, "t": "quran", "x": "كما يمسك الطير يمسك السماوات والأرض: ﴿إن الله يمسك السماوات والأرض أن تزولا﴾، ﴿ويمسك السماء أن تقع على الأرض إلا بإذنه﴾.", "r": "فاطر: 41؛ الحج: 65", "s": ["adwa"]}, {"id": "tayr-khasf-munasaba", "a": 19, "t": "munasaba", "x": "توجيه النظر إلى الطير بعد التخويف بالخسف: الأرض معلّقة في الهواء كالطير لا يمسكها إلا الله، وإيقاع الخسف بها كإسقاط الطير من الجو، والجميع بقدرته.", "s": ["adwa"]}, {"id": "tayr-saadi", "a": 19, "t": "aqida", "x": "«ما يمسكهن إلا الرحمن»: سخّر لهن الجو وجعل أجسادها مهيأة للطيران؛ ومن اعتبر بحال الطير دلّته على قدرة الباري وعنايته وأنه المستحق للعبادة وحده.", "s": ["saadi"]}, {"id": "ghurur-aliha", "a": 20, "t": "aqida", "x": "«إن الكافرون إلا في غرور»: غرورهم ظنهم أن آلهتهم تقرّبهم إلى الله زلفى وأنها تنفع أو تضر؛ ولا جند يدفع عنهم ما أراد الله بهم.", "s": ["tabari", "ibnkathir", "qurtubi", "ibnashur"]}, {"id": "jund-mufrad", "a": 20, "t": "irab", "x": "لفظ «جند» يوحَّد، ولذا قال «هذا الذي هو جند لكم»؛ والاستفهام إنكاري: لا جند لكم من سوى الرحمن.", "s": ["qurtubi", "baghawi", "ibnjawzi"]}, {"id": "ghurur-shayatin", "a": 20, "t": "tafsir", "x": "«في غرور»: من الشياطين، تغرّهم بأن لا عذاب ولا حساب.", "s": ["qurtubi", "baghawi", "ibnjawzi"]}, {"id": "jund-tajiz", "a": 20, "t": "balagha", "x": "الاستفهام في «أمّن هذا الذي هو جند لكم» للتعجيز عن التعيين فيؤول إلى النفي، والإشارة إلى جند مفروض في الأذهان؛ ويجوز أن يشار إلى أصنامهم حول الكعبة فيكون استفهام تحقير، ونظيره ﴿من ذا الذي يشفع عنده إلا بإذنه﴾.", "r": "البقرة: 255", "s": ["ibnashur"]}, {"id": "rasm-amman", "a": 20, "t": "qiraat", "x": "كُتبت «أمّن» في المصحف بميم واحدة كـ﴿عمّ يتساءلون﴾ ولا تُقرأ إلا مشددة؛ إذ المعتبر في القراءة الرواية لا الكتابة، وإنما يُكتب القرآن للإعانة على مراجعته.", "s": ["ibnashur"]}, {"id": "jund-istidad", "a": 20, "t": "hidaya", "x": "جيء بالجملة الاسمية «هو جند لكم» للدوام، لأن الجند يكون على استعداد للنصر متى دُعي، كحديث: «خير الناس رجل ممسك بعنان فرسه، كلما سمع هيعة طار إليها».", "s": ["ibnashur"]}, {"id": "ghurur-tarif", "a": 20, "t": "lugha", "x": "الغرور: ظنّ النفس وقوع أمر نافع لها بمخايل تتوهمها وهو بخلاف ذلك؛ والظرفية «في غرور» مجازية لشدة التلبس، والقصر إضافي يقلب اعتقادهم أنهم في مأمن بحماية آلهتهم.", "s": ["ibnashur"]}, {"id": "amman-irab", "a": 20, "t": "irab", "x": "«أمّن» أصلها «أم مَن» أُدغمت الميم، و«أم» هنا بمعنى «بل» المنقطعة، و«مَن» اسم استفهام مبتدأ و«هذا» خبره؛ والمعنى: لا أحد ينصركم ولا يرزقكم. وقرأ طلحة بتخفيف الميم.", "s": ["ibnashur", "bahr"]}, {"id": "nasr-allah", "a": 20, "t": "aqida", "x": "الله هو الناصر المعزّ المذلّ، ولو اجتمع الخلق على نصر عبد لم ينفعوه بمثقال ذرة؛ فاستمرار الكافرين على كفرهم بعد علمهم بذلك غرور وسفه.", "s": ["saadi"]}, {"id": "utuw-nufur", "a": 21, "t": "lugha", "x": "«لجّوا في عتوّ ونفور»: تمادَوا في طغيان واستكبار ونفور عن الحق؛ ابن عباس: في ضلال، مجاهد: كفور.", "s": ["tabari", "ibnkathir", "qurtubi", "baghawi", "ibnjawzi", "bahr", "saadi"]}, {"id": "rizq-matar", "a": 21, "t": "tafsir", "x": "«أمن هذا الذي يرزقكم»: من الذي يرزقكم المطر إن أمسكه الله عنكم؟", "s": ["baghawi", "ibnjawzi"]}, {"id": "rizq-laff-nashr", "a": 21, "t": "munasaba", "x": "«أمّن هذا الذي يرزقكم» ناظر إلى «وكلوا من رزقه» على طريقة اللف والنشر المعكوس؛ وجيء بالمضارع «يرزقكم» للتجدد لأن الحاجة إلى الرزق مستمرة.", "s": ["ibnashur"]}, {"id": "lajju-istinaf", "a": 21, "t": "balagha", "x": "«بل لجّوا في عتو ونفور» استئناف بياني: كأن سائلًا قال: لعلهم انتفعوا بهذه الآيات والنذر؟ فأُجيب بإبطال ظنه.", "s": ["ibnashur"]}, {"id": "utuw-nufur-ibn-ashur", "a": 21, "t": "lugha", "x": "«لجّ»: اشتد في الخصومة، «العتو»: التكبر والطغيان، «النفور»: الاشمئزاز والهروب؛ أي استمروا على العناد تكبرًا حرصًا على سيادتهم، ونفورًا عما يخالف أهواءهم.", "s": ["ibnashur"]}, {"id": "nufur-thiql", "a": 21, "t": "lugha", "x": "«عتوّ»: تكبّر وعناد، «نفور»: شِراد عن الحق لثقله عليهم.", "s": ["bahr"]}, {"id": "rizq-saba", "a": 21, "t": "quran", "x": "صرّح بالسؤال وجوابه في: ﴿قل من يرزقكم من السماوات والأرض قل الله﴾، و﴿هل من خالق غير الله يرزقكم من السماء والأرض﴾؛ فمن يقدر على الخلق هو الذي يملك الرزق ﴿الله الذي خلقكم ثم رزقكم﴾.", "r": "سبأ: 24؛ فاطر: 3؛ يونس: 31؛ الروم: 40", "s": ["adwa"]}, {"id": "rizq-ankabut", "a": 21, "t": "quran", "x": "ردٌّ على من يطلب الرزق من غير الله: ﴿إن الذين تعبدون من دون الله لا يملكون لكم رزقا فابتغوا عند الله الرزق واعبدوه واشكروا له﴾.", "r": "العنكبوت: 17؛ النحل: 73", "s": ["adwa"]}, {"id": "rizq-abasa", "a": 21, "t": "quran", "x": "تفصيل الرزق مما يعجز عنه الخلق: ﴿فلينظر الإنسان إلى طعامه أنا صببنا الماء صبا ثم شققنا الأرض شقا...﴾؛ وقوام ذلك كله إنزال الماء، فإذا أمسكه الله لم يقدر مخلوق على إنزاله.", "r": "عبس: 24-32", "s": ["adwa"]}, {"id": "aisha-yaqin", "a": 21, "t": "athar", "x": "عائشة رضي الله عنها: والله لا يكمل إيمان العبد حتى يكون يقينه بما عند الله أعظم مما بيده؛ فمن علم أن الأرزاق بيد الله لم يتوجه بسؤال إلا إليه.", "r": "عائشة", "s": ["adwa"]}, {"id": "razzaq-ibada", "a": 21, "t": "aqida", "x": "الرزق كله من الله، والخلق لا يقدرون على رزق أنفسهم فكيف بغيرهم؟ فالرازق المنعم هو المستحق أن يُفرد بالعبادة (توحيد الربوبية دليل على توحيد الألوهية).", "s": ["adwa", "saadi"]}, {"id": "mukibban-mathal", "a": 22, "t": "khilaf", "x": "«أفمن يمشي مكبًّا على وجهه»: قيل مثلٌ ضربه الله للكافر في ضلاله والمؤمن في هداه (ابن عباس، مجاهد، الضحاك)، وقيل هو حشر الكافر على وجهه يوم القيامة (قتادة).", "s": ["tabari", "ibnkathir", "qurtubi", "baghawi", "ibnjawzi", "ibnashur", "bahr"]}, {"id": "hashr-wajh", "a": 22, "t": "hadith", "x": "قيل: يا رسول الله كيف يُحشر الكافر على وجهه؟ قال: «إن الذي أمشاه على رجليه قادر أن يحشره يوم القيامة على وجهه».", "r": "متفق عليه من حديث أنس", "s": ["tabari", "ibnkathir", "bahr"]}, {"id": "mukibb-sarf", "a": 22, "t": "lugha", "x": "«مُكِبًّا» من أكبّ اللازم؛ فإذا تعدّى حُذفت الألف: كبّه الله على وجهه. واستشهد ببيت الأعشى.", "s": ["tabari", "qurtubi", "ibnjawzi"]}, {"id": "mukibban-dunya-akhira", "a": 22, "t": "tafsir", "x": "جمع ابن كثير القولين: هو مثلٌ للمؤمن والكافر في الدنيا، وكذلك حالهم في الآخرة؛ المؤمن يُحشر سويًّا على صراط مستقيم إلى الجنة، والكافر على وجهه إلى النار ﴿فاهدوهم إلى صراط الجحيم﴾.", "r": "الصافات: 22-26", "s": ["ibnkathir"]}, {"id": "mukibban-abu-jahl", "a": 22, "t": "nuzul", "x": "ابن عباس والكلبي: المكبّ على وجهه أبو جهل، والماشي سويًّا رسول الله ﷺ؛ وقيل: أبو بكر، وقيل: حمزة، وقيل: عمار بن ياسر (عكرمة). والأظهر أنها عامة في كل كافر ومؤمن.", "r": "ابن عباس، الكلبي، عكرمة", "s": ["qurtubi", "ibnashur", "bahr"]}, {"id": "mukibban-ama", "a": 22, "t": "tafsir", "x": "«مكبًّا»: منكّسًا رأسه لا ينظر أمامه ولا يمينه ولا شماله فلا يأمن العثار، بخلاف السويّ المعتدل الناظر؛ ويجوز أن يريد الأعمى الذي لا يهتدي الطريق.", "s": ["qurtubi", "baghawi", "ibnjawzi"]}, {"id": "mukibban-sabil", "a": 22, "t": "balagha", "x": "الذي انقدح لابن عاشور: الآية ثلاث استعارات تمثيلية؛ المشرك الموزّع بين آلهة كثيرة كسائرٍ في أرض بلا جادّة يتتبع بُنيّات الطريق مُكبًّا يتوسّم الآثار، والمؤمن برب واحد كماشٍ على جادة واضحة مستوٍ؛ ويفسره ﴿ولا تتبعوا السبل فتفرق بكم عن سبيله﴾ و﴿أأرباب متفرقون خير أم الله الواحد القهار﴾.", "r": "الأنعام: 153؛ يوسف: 39", "s": ["ibnashur"]}, {"id": "mukibb-sayrura", "a": 22, "t": "lugha", "x": "«مُكِبّ» اسم فاعل من «أكبّ» والهمزة للصيرورة (صار ذا كبّ) كأقشع السحاب وأنفض القوم وأرملوا؛ وهي أفعال قليلة جاء فيها المجرد متعديًا والمهموز قاصرًا.", "s": ["ibnashur"]}, {"id": "ahda-maslub", "a": 22, "t": "balagha", "x": "«أهدى» اسم تفضيل مسلوب المفاضلة لأن المكبّ لا اهتداء عنده، كـ﴿رب السجن أحب إلي﴾، وفيه تهكم؛ و«سويًّا»: فعيل بمعنى فاعل أي شديد الاستواء.", "s": ["ibnashur"]}, {"id": "mukibb-mutawaa", "a": 22, "t": "irab", "x": "«مكبًّا» حال من «أكبّ» اللازم، و«كبّ» متعدٍّ: ﴿فكبت وجوههم في النار﴾، ومطاوعه «انكبّ»؛ وردّ أبو حيان على الزمخشري قوله إن «أفعل» لا يأتي مطاوعًا.", "r": "النمل: 90", "s": ["bahr"]}, {"id": "ahda-tafdil", "a": 22, "t": "balagha", "x": "«أهدى» أفعل تفضيل على سبيل التنزّل كقولهم: العسل أحلى أم الخل؟ والاستفهام لا تراد حقيقته، بل كل سامع يجيب بأن الماشي سويًّا أهدى.", "s": ["bahr"]}, {"id": "mukibban-saadi", "a": 22, "t": "hidaya", "x": "المكبّ: من انتكس قلبه فصار الحق عنده باطلًا والباطل حقًا، والسويّ: العالم بالحق المؤثر له العامل به؛ «والأحوال أكبر شاهد من الأقوال».", "s": ["saadi"]}, {"id": "shukr-hawas", "a": 23, "t": "hidaya", "x": "السمع للسماع، والأبصار للرؤية، والأفئدة للعقل؛ وقليلٌ شكرُ الناس على هذه النعم.", "s": ["tabari"]}, {"id": "shukr-isti'mal", "a": 23, "t": "hidaya", "x": "«قليلا ما تشكرون»: ما أقلّ استعمالكم هذه القوى (السمع والبصر والعقل) في طاعة الله وامتثال أمره وترك زواجره؛ فالشكر استعمال النعمة في الطاعة.", "s": ["ibnkathir"]}, {"id": "tawbikh-shirk", "a": 23, "t": "aqida", "x": "«قل هو الذي أنشأكم»: أمر نبيه أن يعرّفهم قبح شركهم مع اعترافهم بأن الله خالقهم.", "s": ["qurtubi"]}, {"id": "qalilan-nafy", "a": 23, "t": "balagha", "x": "«قليلا ما تشكرون»: أي لا تشكرون؛ كقولك: قلّما أفعل كذا، أي لا أفعله. فالقلة هنا كناية عن النفي.", "s": ["qurtubi", "baghawi", "ibnashur", "bahr"]}, {"id": "qalilan-khilaf", "a": 23, "t": "khilaf", "x": "«قليلا ما تشكرون»: قولان: لا يشكرون أصلًا (مقاتل)، أو يشكرون قليلًا (أبو عبيد).", "s": ["ibnjawzi"]}, {"id": "qul-tafannun", "a": 23, "t": "balagha", "x": "انتقال إلى خطابهم على لسان الرسول ﷺ «قل» تفننًا في البيان وتنشيطًا للأذهان وترفيعًا لقدر النبي ﷺ؛ وتكرر الأمر «قل» خمس مرات بلا عاطف اهتمامًا بكل مقالة.", "s": ["ibnashur"]}, {"id": "usul-furu", "a": 23, "t": "munasaba", "x": "انتقال من الاستدلال بأصول المخلوقات (السماوات والأرض والموت والحياة) إلى فروعها (خلق الإنسان ومداركه).", "s": ["ibnashur"]}, {"id": "sam-ifrad", "a": 23, "t": "lugha", "x": "أُفرد «السمع» لأن أصله مصدر (حالة السمع)، وجُمعت «الأبصار» جمع بصر بمعنى العين، و«الأفئدة» القلوب والمراد العقول.", "s": ["ibnashur"]}, {"id": "qasr-ifrad-insha", "a": 23, "t": "aqida", "x": "«هو الذي أنشأكم» قصر إفراد تنزيلًا لهم منزلة من يعتقد مشاركة الأصنام لله في الإنشاء وإعطاء الإحساس والإدراك.", "s": ["ibnashur"]}, {"id": "qalilan-irab", "a": 23, "t": "irab", "x": "«قليلا» نعت لمصدر محذوف و«ما» زائدة: تشكرون شكرًا قليلًا؛ وقال ابن عطية: قد يريد نفي الشكر جملة فعبّر بالقلة كقولهم: أرض قلّما تنبت كذا، أي لا تنبته.", "s": ["bahr"]}, {"id": "hawas-afdal", "a": 23, "t": "hidaya", "x": "السمع والأبصار والأفئدة أفضل أعضاء البدن وأكمل القوى؛ ومع ذلك «قليلا ما تشكرون»: قليلٌ منكم الشاكر، وقليلٌ منكم الشكر.", "s": ["saadi"]}, {"id": "dharaakum", "a": 24, "t": "lugha", "x": "«ذرأكم»: بثّكم ونشركم في أقطار الأرض مع اختلاف ألسنتكم وألوانكم، «وإليه تحشرون»: يجمعكم بعد التفرق كما فرقكم ويعيدكم كما بدأكم.", "s": ["ibnkathir", "qurtubi", "ibnjawzi", "saadi"]}, {"id": "dhara-ikthar", "a": 24, "t": "lugha", "x": "الذرء: الإكثار من الموجود، فهو أخص من «أنشأكم»، كقوله: ﴿هو أنشأكم من الأرض واستعمركم فيها﴾.", "r": "هود: 61", "s": ["ibnashur"]}, {"id": "hashr-kinaya-mawt", "a": 24, "t": "balagha", "x": "«وإليه تحشرون»: كناية عن الموت بمرتبتين من الملازمة (الحشر بعد البعث، والبعث بعد الموت)، مع إدماج الإنذار بالبعث؛ وتقديم «إليه» للاهتمام والفاصلة لا للاختصاص.", "s": ["ibnashur"]}, {"id": "mata-istihza", "a": 25, "t": "tafsir", "x": "«متى هذا الوعد»: سؤال استهزاء منهم بيوم القيامة والعذاب الموعود.", "s": ["qurtubi"]}, {"id": "mata-tahakkum", "a": 25, "t": "balagha", "x": "«متى هذا الوعد» استفهام تهكم، وعبّروا بلفظ «الوعد» استنجازًا له لأن شأن الوعد الوفاء، وجيء بالمضارع «ويقولون» لتكرّر قولهم ذلك؛ ونظيره ﴿ويقولون متى هو﴾.", "r": "الإسراء: 51", "s": ["ibnashur"]}, {"id": "mata-zulm", "a": 25, "t": "hidaya", "x": "جعلوا علامة صدق الرسل أن يخبروهم بوقت الساعة، وهذا ظلم وعناد؛ إذ لا ملازمة بين صدق الخبر ومعرفة وقته، والصدق يُعرف بأدلته.", "s": ["saadi"]}, {"id": "ilm-saa", "a": 26, "t": "aqida", "x": "علم الساعة ومتى تقوم عند الله وحده، والنبي ﷺ نذير مبين فحسب.", "s": ["tabari", "ibnkathir", "qurtubi", "ibnashur", "saadi"]}, {"id": "ilm-saa-araf", "a": 26, "t": "quran", "x": "نظيرها: ﴿قل إنما علمها عند ربي لا يجليها لوقتها إلا هو﴾.", "r": "الأعراف: 187", "s": ["qurtubi"]}, {"id": "uslub-hakim", "a": 26, "t": "balagha", "x": "أُجيب سؤالهم على الأسلوب الحكيم بظاهر الاستفهام عن الوقت: «إنما العلم عند الله» (قصر حقيقي)، «وإنما أنا نذير مبين» (قصر إضافي): لا أتجاوز الإنذار إلى العلم بالوقت.", "s": ["ibnashur"]}, {"id": "zulfa", "a": 27, "t": "lugha", "x": "«زُلفة»: قريبًا، أي لمّا عاينوه (الحسن، مجاهد، قتادة).", "s": ["tabari", "qurtubi", "saadi"]}, {"id": "taddaun", "a": 27, "t": "qiraat", "x": "الجمهور «تدَّعون» بالتشديد (تفتعلون من الدعاء: تستعجلون)، وقرأ قتادة والضحاك «تَدْعون» مخففة: تدعون الله بالعذاب. ورجّح الطبري قراءة الأمصار.", "s": ["tabari", "qurtubi", "baghawi", "ibnjawzi", "ibnashur"]}, {"id": "taddaun-anfal", "a": 27, "t": "quran", "x": "استشهد قتادة لقراءة التخفيف بقوله: ﴿وإذ قالوا اللهم إن كان هذا هو الحق من عندك فأمطر علينا حجارة من السماء﴾، أي كانوا يدعون بالعذاب.", "r": "الأنفال: 32", "s": ["tabari", "qurtubi", "ibnashur"]}, {"id": "zulfa-qarib", "a": 27, "t": "hidaya", "x": "رأوه قريبًا لأن كل آتٍ قريب وإن طال زمنه، فبدا لهم ما لم يكونوا يحتسبون، كقوله: ﴿وبدا لهم من الله ما لم يكونوا يحتسبون﴾.", "r": "الزمر: 47-48", "s": ["ibnkathir"]}, {"id": "zulfa-khilaf", "a": 27, "t": "khilaf", "x": "«رأوه»: أكثر المفسرين: عذاب الآخرة، وقال مجاهد: عذاب بدر، وقيل: الحشر، وقال ابن عباس: رأوا عملهم السيئ قريبًا. و«زلفة» مصدر بمعنى مُزدلِف أي قريب.", "s": ["qurtubi", "baghawi", "ibnjawzi"]}, {"id": "siat-wujuh", "a": 27, "t": "quran", "x": "«سيئت وجوه الذين كفروا»: ظهر فيها السوء وعلتها سِمَة الكفر، كقوله: ﴿يوم تبيض وجوه وتسود وجوه﴾.", "r": "آل عمران: 106", "s": ["qurtubi", "baghawi", "ibnjawzi"]}, {"id": "siat-qiraa", "a": 27, "t": "qiraat", "x": "قرأ نافع وابن عامر والكسائي «سِيئت» بإشمام الكسرة الضم، والباقون بالكسر الخالص طلبًا للخفة.", "s": ["qurtubi", "ibnashur", "bahr"]}, {"id": "taddaun-sad", "a": 27, "t": "quran", "x": "قال قتادة في قراءة التخفيف: هو قولهم ﴿ربنا عجل لنا قطنا قبل يوم الحساب﴾.", "r": "ص: 16", "s": ["qurtubi"]}, {"id": "taddaun-nahhas", "a": 27, "t": "lugha", "x": "«تدّعون» و«تدْعون» بمعنى، كقدَر واقتدر، إلا أن في «افتعل» معنى شيء بعد شيء (النحاس). وقيل: تدّعون الأباطيل، وعن ابن عباس: تكذّبون.", "s": ["qurtubi"]}, {"id": "zulfa-masdar", "a": 27, "t": "irab", "x": "«زُلفة» اسم يوصف به المصدر، يستوي فيه المذكر والمؤنث والواحد والمثنى والجمع.", "s": ["baghawi"]}, {"id": "qaala-khazana", "a": 27, "t": "tafsir", "x": "«وقيل هذا الذي كنتم به تدّعون»: القائل هم خزنة جهنم.", "s": ["baghawi"]}, {"id": "taddaun-aqwal", "a": 27, "t": "khilaf", "x": "«تدّعون»: قولان: بمعنى تدعون (افتعال من الدعاء: تطلبون وتستعجلون) قاله الفراء وابن قتيبة، أو: تدّعون الأباطيل أنكم لا تُبعثون، واختاره الزجاج.", "s": ["ibnjawzi", "bahr"]}, {"id": "madi-tahaqquq", "a": 27, "t": "balagha", "x": "«فلما رأوه... سيئت» جيء بالماضي في أمر مستقبل لتحقق وقوعه كـ﴿أتى أمر الله﴾؛ والفاء فصيحة تقديرها: فحلّ بهم الوعد فلما رأوه.", "s": ["ibnashur"]}, {"id": "zulfa-masdar-mubalagha", "a": 27, "t": "irab", "x": "«زُلفة» اسم مصدر «زلِف» إذا قرب، والإخبار بالمصدر للمبالغة: رأوه شديد القرب أخذ ينالهم.", "s": ["ibnashur"]}, {"id": "siat-tadmin", "a": 27, "t": "balagha", "x": "أُسند السوء إلى الوجوه لتضمين «سيئت» معنى «كلحت»، أي سوء شديد تظهر آثاره على الوجوه، كما أسند الأعشى الخوف إلى الأعين.", "s": ["ibnashur"]}, {"id": "taddaun-tadmin", "a": 27, "t": "irab", "x": "«تدّعون» مضارع ادّعى، ومفعوله محذوف أي تدّعون أنه لا يكون، وعُدّي بالباء «به» لتضمينه معنى «تكذّبون»؛ وحُذف القائل «وقيل» إذ المقصود المقول (ملائكة المحشر أو الخزنة).", "s": ["ibnashur"]}, {"id": "hadha-ahqaf", "a": 27, "t": "quran", "x": "القصر في «هذا الذي كنتم به تدّعون» تعريض بأنهم لشدة جحودهم إذا رأوا الوعد حسبوه شيئًا آخر، كقوله: ﴿فلما رأوه عارضا مستقبل أوديتهم قالوا هذا عارض ممطرنا﴾.", "r": "الأحقاف: 24", "s": ["ibnashur"]}, {"id": "zulfa-irab", "a": 27, "t": "irab", "x": "«زُلفة»: ذات قرب، أو ظرف بتقدير: مكانًا ذا زلفة؛ وقال الحسن: عيانًا، وابن زيد: حاضرًا.", "s": ["bahr"]}, {"id": "siat-kaaba", "a": 27, "t": "tafsir", "x": "«سيئت»: ساءت رؤيةُ العذاب وجوههم فظهر فيها السوء والكآبة وغشيها السواد كمن يُساق إلى القتل.", "s": ["bahr"]}, {"id": "taddaun-bahr", "a": 27, "t": "qiraat", "x": "«تدْعون» بالتخفيف: قراءة أبي رجاء والضحاك والحسن وقتادة ويعقوب، ورُويت عن أبي بكر عن عاصم والأصمعي عن نافع؛ وهي تقوّي أن المشدّدة من الدعاء (الاستعجال).", "s": ["bahr"]}, {"id": "ahlakani", "a": 28, "t": "tafsir", "x": "«إن أهلكني الله ومن معي أو رحمنا»: موتُنا أو حياتنا لا ينجيكم من عذاب الله، فلا فائدة لكم في تربّص هلاكنا ولا في استعجال العذاب.", "s": ["tabari", "ibnkathir", "qurtubi", "baghawi", "saadi"]}, {"id": "ahlakani-tawba", "a": 28, "t": "hidaya", "x": "«فمن يجير الكافرين»: خلّصوا أنفسكم، فلا منقذ لكم من الله إلا التوبة والرجوع إلى دينه، ولا ينفعكم ما تتمنونه لنا من الهلاك.", "s": ["ibnkathir"]}, {"id": "tarabbus-tur", "a": 28, "t": "quran", "x": "كان مشركو مكة يتمنون موت النبي ﷺ، كما قال: ﴿أم يقولون شاعر نتربص به ريب المنون﴾.", "r": "الطور: 30", "s": ["qurtubi", "baghawi", "ibnashur", "saadi"]}, {"id": "ahlakani-qiraa", "a": 28, "t": "qiraat", "x": "أسكن حمزة الياء في «أهلكنيْ»، وفتحها الباقون؛ وأسكن الكوفيون ياء «ومن معيْ» إلا حفصًا فإنه فتحها.", "s": ["qurtubi", "ibnjawzi", "ibnashur"]}, {"id": "ahlakani-khawf", "a": 28, "t": "hidaya", "x": "معنى آخر عن ابن عباس: إن كنا نحن مع إيماننا خائفين أن يهلكنا الله بذنوبنا لأن حكمه نافذ فينا، فمن يجيركم من عذابه وأنتم كافرون؟", "s": ["baghawi", "ibnjawzi"]}, {"id": "khawf-raja", "a": 28, "t": "hidaya", "x": "المؤمنون مع إيمانهم بين الخوف والرجاء، فمن يجير الكافرين مع كفرهم ولا رجاء لهم كرجاء المؤمنين؟", "s": ["ibnjawzi"]}, {"id": "tarabbus-ayat", "a": 28, "t": "quran", "x": "موت أحد أو حياته لا يغني عن غيره ما جرّه عمله: ﴿فإما نذهبن بك فإنا منهم منتقمون أو نرينك الذي وعدناهم﴾، ﴿أفإن مت فهم الخالدون﴾، ﴿إنك ميت وإنهم ميتون﴾؛ ويُنسب للشافعي: «تمنّى رجالٌ أن أموتَ فإن أمُتْ ... فتلك سبيلٌ لستُ فيها بأوحدِ».", "r": "الزخرف: 41-42؛ الأنبياء: 34؛ الزمر: 30", "s": ["ibnashur"]}, {"id": "hayat-rahma", "a": 28, "t": "hidaya", "x": "مقابلة «أهلكني» بـ«رحمنا» تدل على أن الحياة رحمة وتأخير الأجل نعمة، فحياة المؤمن تكثر فيها بركة الإيمان والعمل الصالح.", "s": ["ibnashur"]}, {"id": "wafat-nabi-hikma", "a": 28, "t": "hadith", "x": "لم يؤخّر الله أجل نبيه ﷺ لحِكَم، منها إكمال الدين، كما أشارت سورة النصر، وفي الحديث: «حياتي خير لكم وموتي خير لكم»؛ وعوّضه برفع الذكر وبردّ روحه عليه كلما سلّم عليه أحد.", "r": "النصر؛ الشرح: 4", "s": ["ibnashur"]}, {"id": "maiyya-majaz", "a": 28, "t": "lugha", "x": "المعية في «ومن معي» مجازية بمعنى الموافقة في الدين، كقوله: ﴿محمد رسول الله والذين معه﴾.", "s": ["ibnashur"]}, {"id": "kafirin-illa", "a": 28, "t": "balagha", "x": "ذكر وصف «الكافرين» دون «يجيركم» إيماء إلى علة الحكم (الكفر)، مع حذف تقديره: من يجيركم فإنكم كافرون ولا مجير للكافرين؛ وتنكير «عذاب» للتهويل.", "s": ["ibnashur"]}, {"id": "duaa-halak", "a": 28, "t": "nuzul", "x": "رُوي أن الكفار كانوا يدعون على النبي ﷺ وأصحابه بالهلاك، وقيل: كانوا يتآمرون على قتلهم؛ فأُمر أن يقول: «إن أهلكني الله» كما تريدون «أو رحمنا» بالنصر عليكم، فمن يجيركم من العذاب الذي سببه كفركم؟", "s": ["bahr"]}, {"id": "tawakkul", "a": 29, "t": "hidaya", "x": "«آمنّا به وعليه توكلنا»: صدّقنا به واعتمدنا عليه في أمورنا ووثقنا به.", "s": ["tabari", "ibnkathir", "qurtubi", "baghawi", "saadi"]}, {"id": "tawakkul-hud", "a": 29, "t": "quran", "x": "قرن الإيمان بالتوكل كقوله: ﴿فاعبده وتوكل عليه﴾.", "r": "هود: 123", "s": ["ibnkathir"]}, {"id": "fasatalamun-qiraa", "a": 29, "t": "qiraat", "x": "قرأ الكسائي «فسيعلمون» بالياء على الخبر، والباقون بالتاء على الخطاب تهديدًا لهم.", "s": ["qurtubi", "baghawi", "ibnjawzi", "ibnashur", "bahr"]}, {"id": "taqdim-alayhi", "a": 29, "t": "balagha", "x": "أُخّر مفعول «آمنّا» وقُدّم مفعول «توكلنا» («عليه»): لأن «آمنّا» تعريض بالكافرين: آمنّا ولم نكفر كما كفرتم، و«عليه توكلنا» خصوصًا، لا على ما تتكلون عليه من رجالكم وأموالكم (الزمخشري).", "s": ["qurtubi", "ibnashur"]}, {"id": "rahman-ma-rahmana", "a": 29, "t": "munasaba", "x": "جاء «قل هو الرحمن» مناسبًا لـ«أو رحمنا»: المسلمون آمنوا بالرحمن فهم مظنّة رحمته، والمشركون أنكروا هذا الاسم فهم أحرياء بالحرمان من آثاره.", "s": ["ibnashur"]}, {"id": "rahman-rahima", "a": 29, "t": "munasaba", "x": "لما قال «أو رحمنا» قال بعدها «قل هو الرحمن»، ثم ذكر ما به النجاة وهو الإيمان والتفويض إلى الله.", "s": ["bahr"]}, {"id": "tawakkul-takhsis", "a": 29, "t": "aqida", "x": "الإيمان يشمل التصديق والأعمال الباطنة والظاهرة، وخُصّ التوكل بالذكر لأن وجود الأعمال وكمالها متوقف عليه، وهو من لوازم الإيمان: ﴿وعلى الله فتوكلوا إن كنتم مؤمنين﴾.", "r": "المائدة: 23", "s": ["saadi"]}, {"id": "ghawr", "a": 30, "t": "lugha", "x": "«غَوْرًا»: غائرًا لا تناله الدلاء؛ وُصف بالمصدر مبالغة كقولهم: ماءٌ غَوْر. و«معين»: الظاهر الجاري الذي تراه العيون (ابن عباس: عذب).", "s": ["tabari", "ibnkathir", "qurtubi", "baghawi", "ibnjawzi", "ibnashur", "saadi"]}, {"id": "main-nima", "a": 30, "t": "hidaya", "x": "الغائر عكس النابع، لا يُنال بالفؤوس الحِداد ولا السواعد الشِّداد؛ ومن فضل الله أن أنبع المياه وأجراها في أقطار الأرض بحسب حاجة العباد.", "s": ["ibnkathir"]}, {"id": "zamzam", "a": 30, "t": "nuzul", "x": "كان ماء قريش من بئرين: بئر زمزم وبئر ميمون؛ فالخطاب لهم بما يعرفون.", "s": ["qurtubi", "baghawi", "ibnashur"]}, {"id": "main-ishtiqaq", "a": 30, "t": "irab", "x": "«معين»: إما مفعول من العين أي ظاهر تراه العيون، وإما فعيل من «مَعَنَ الماء» إذا كثر.", "s": ["qurtubi"]}, {"id": "main-ilzam", "a": 30, "t": "hidaya", "x": "لا بد أن يقولوا: لا يأتينا به إلا الله؛ فيقال لهم: فلِمَ تشركون به من لا يقدر على أن يأتيكم بالماء؟", "s": ["qurtubi"]}, {"id": "zamzam-kalbi", "a": 30, "t": "athar", "x": "الكلبي ومقاتل: «ماؤكم» يعني ماء زمزم.", "r": "الكلبي، مقاتل", "s": ["baghawi"]}, {"id": "makka-miyah", "a": 30, "t": "nuzul", "x": "إيماء إلى عذاب القحط: فمكة قليلة المياه لم يكن بها قبل زمزم ماء، ثم حُفرت بئر ميمون بن خالد الحضرمي قُبيل البعثة؛ وقد أصابهم بعد الهجرة قحط شديد هو المشار إليه في سورة الدخان.", "s": ["ibnashur"]}, {"id": "ghawr-kahf", "a": 30, "t": "quran", "x": "«غورا» كقوله في صاحب الجنة: ﴿أو يصبح ماؤها غورا فلن تستطيع له طلبا﴾، ونظير الإنذار ما في سورة القلم من قصة أصحاب الجنة.", "r": "الكهف: 41؛ القلم: 17-33", "s": ["ibnashur"]}, {"id": "main-yanabi", "a": 30, "t": "quran", "x": "انحباس المطر يتبعه غور مياه الآبار لأن مددها من ماء السماء: ﴿ألم تر أن الله أنزل من السماء ماء فسلكه ينابيع في الأرض﴾.", "r": "الزمر: 21", "s": ["ibnashur"]}, {"id": "main-adhab-khass", "a": 30, "t": "munasaba", "x": "لما ذكر العذاب المطلق ختم بذكر فقد ما به حياة النفوس وهو الماء، وهو عذاب مخصوص.", "s": ["bahr"]}, {"id": "jawab-shart", "a": 30, "t": "irab", "x": "جواب «إن أهلكني» هو «فمن يجير»، وجواب «إن أصبح» هو «فمن يأتيكم».", "s": ["bahr"]}, {"id": "mustahzi-ain", "a": 30, "t": "athar", "x": "تُليت هذه الآية عند بعض المستهزئين فقال: تجيء به الفؤوس والمعاول، فذهب ماء عينيه (فعوقب بغور ماء عينيه). وسمّاه ابن عاشور نقلًا عن الكشاف: محمد بن زكريا الطبيب.", "s": ["ibnashur", "bahr"]}, {"id": "main-muminun", "a": 30, "t": "quran", "x": "نظيرها: ﴿وأنزلنا من السماء ماء بقدر فأسكناه في الأرض وإنا على ذهاب به لقادرون﴾.", "r": "المؤمنون: 18", "s": ["adwa"]}, {"id": "main-istifham-nafy", "a": 30, "t": "balagha", "x": "«فمن يأتيكم بماء معين» استفهام بمعنى النفي: لا يقدر على ذلك أحد غير الله؛ وخصّ الماء لأن الله جعل منه كل شيء حي.", "s": ["ibnashur", "saadi"]}]};
